window.SSS_NOUN_CARDS = [{"number":1,"name":"Chick","image":"assets/noun-cards/001.jpeg","imageOk":true,"dialogue":"亲子对话\nHi little darling.\nToday we are going to look at one animal, It is a chick, chick,chick.\nWhat color is the chick？\nit's yellow. It's a yellow chick.\nWhat does the chick say?\nA chick says chuckle ,chuckle,chukle.\nWhat does the chick like to eat?  \nen.Rice and corn. A chick likes to eat rice and corn.\nWho is the chick's mother?\nA hen. A hen is the chick's mother.\nPlease read after to me one more time.chick chick.","translation":"这段亲子对话围绕“Chick”展开，可结合图片逐句理解和跟读。","words":[{"word":"corn","ipa":"kɔːn","meaning":"谷物；小麦;燕麦;玉蜀黍；玉米;谷粒;一颗谷粒;老茧；硬皮;老生常谈；过于感伤的事物（如歌曲等）;硬颗粒;","collocation":"use corn","example":"I can use corn.","sourceExample":"farmers growing wheat, corn, or other crops","sourceTranslation":"种植小麦、玉米或其他作物的农民"},{"word":"chuckle","ipa":"ˈtʃʌkl","meaning":"轻声地笑；暗笑;咯咯地叫;","collocation":"use chuckle","example":"I can use chuckle.","sourceExample":"He was unable to submerge a deep chuckle.","sourceTranslation":"他忍不住轻声长笑"}],"patterns":[{"name":"sth are very ...  You have ...","examples":["Your hair is very long, you have two ponytails.","Your finger is very slender, you have ten slender fingers."],"translations":["我们今天要游泳。","我们现在要刷牙。"]},{"name":"sth has ...","examples":["Fish has one tail.","The rabbit has a short tail."],"translations":["苹果是什么颜色的？","天空是什么颜色的？"]},{"name":"sth can not ...","examples":["The monkey can not fly.","The bird can not swim."],"translations":["你的朋友放学后喜欢做什么？","老师说什么？","兔子想吃什么？"]}],"dialogueTranslations":["你好，小宝贝。","今天我们要看一种动物，它是小鸡，小鸡，小鸡。","小鸡是什么颜色的？","它是黄色的。它是一只黄色的小鸡。","小鸡怎么叫？","小鸡会咯咯叫。","小鸡喜欢吃什么？","玉米和米饭。小鸡喜欢吃米饭和玉米。","谁是小鸡的妈妈？","母鸡。母鸡是小鸡的妈妈。","请再跟我读一遍。小鸡，小鸡。"]},{"number":2,"name":"Duck","image":"assets/noun-cards/002.jpeg","imageOk":true,"dialogue":"亲子对话       \nQuack, Quack, Quack, Um, mimicking a duck 模仿 \nWhat color is the duck ? \nit's yellow. It's a yellow duck.\nA duck can swim, swim, swim, swim on the lake. \nCan you swim a little one?\nI like swimming.\nA duck can swim, A duck says quack, quack, quack. \nI know a song has a duck in it. Let's sing together. \nSix little ducks that I once knew\nFat ones, skinny ones, fair ones too\nBut the one little duck with the feather on her back\nShe led the others with a quack, quack, quack \nQuack, quack, quack, quack, quack, quack\nShe led the others with a quack, quack, quack","translation":"这段亲子对话围绕“Duck”展开，可结合图片逐句理解和跟读。","words":[{"word":"mimicking","ipa":"ˈmɪmɪkɪŋ","meaning":"模仿","collocation":"mimic a sound","example":"She is mimicking a duck.","sourceExample":"She'd had fun mimicking her aunt.","sourceTranslation":"她模仿姑妈的样子，觉得很开心。"},{"word":"lake","ipa":"leɪk","meaning":"湖；湖泊","collocation":"swim in the lake","example":"A duck can swim in the lake.","sourceExample":"The lake had been ottered.","sourceTranslation":"已用网板在湖里捕过鱼了。"},{"word":"once","ipa":"wʌns","meaning":"一次；曾经","collocation":"once upon a time","example":"I saw it once.","sourceExample":"Yes, I watched once.","sourceTranslation":"是的，我看过一次。"},{"word":"skinny","ipa":"ˈskɪnɪ","meaning":"瘦的","collocation":"skinny legs","example":"The duck is skinny.","sourceExample":"I was a skinny little kid.","sourceTranslation":"我当时是个很瘦的小孩"},{"word":"feather","ipa":"ˈfeðə","meaning":"羽毛","collocation":"a feather on its back","example":"The bird has a feather.","sourceExample":"remigial feather","sourceTranslation":"飞羽羽毛"},{"word":"led","ipa":"led","meaning":"带领；引导","collocation":"lead the others","example":"She led the others.","sourceExample":"German-led","sourceTranslation":"由德国人控制的"}],"patterns":[{"name":"Can you","examples":["Can you give the spoon?","Can you sing a song?"],"translations":["你能递给我勺子吗？","你能唱一首歌吗？"]},{"name":"I like doing","examples":["I like reading in the morning.","I like dancing every day.","I like singing children's songs with my little baby."],"translations":["我喜欢早上读书。","我喜欢每天跳舞。","我喜欢和我的小宝宝一起唱儿歌。"]}],"dialogueTranslations":["嘎嘎，嘎嘎，嘎嘎。嗯，在模仿鸭子的叫声。","鸭子是什么颜色的？","它是黄色的。它是一只黄色的鸭子。","鸭子会在湖里游泳。","你会游泳吗，小家伙？","我喜欢游泳。","鸭子会游泳，鸭子会嘎嘎叫。","我知道一首歌里有鸭子。我们一起唱吧。","我曾经认识六只小鸭子。","有胖的、瘦的，还有漂亮的。","但是那只背上有羽毛的小鸭子","她带着其他鸭子嘎嘎叫。","嘎嘎，嘎嘎，嘎嘎，嘎嘎，嘎嘎，嘎嘎。","她带着其他鸭子嘎嘎叫。"]},{"number":3,"name":"Lion","image":"assets/noun-cards/003.jpeg","imageOk":true,"dialogue":"亲子对话       \nRoar！Hi little ones.Today we are going to look at a lion.\nIt's a very fierce animal.It's a lion。\nL-L-L-ion. Roar，A lion.\nA lion is a very big cat.\nIt has a big head. Do you have a big head? En.\nWhere does the lion live?\nLet me see. A lion lives on the grassland.\nA mother lion will take care of the little one.\nThey run and  hunt.\nA lion likes to eat meat.Do you like to eat meat?\nA lion says roar.Let's roar one more time.\nRoar！Lion，lion.","translation":"这段亲子对话围绕“Lion”展开，可结合图片逐句理解和跟读。","words":[{"word":"fierce","ipa":"fɪəs","meaning":"猛烈的；激烈的；狂暴的;极不好的；讨厌的；使人不愉快的;","collocation":"use fierce","example":"I can use fierce."},{"word":"grassland","ipa":"ˈɡrɑːsˌlænd","meaning":"草原;天然牧场;","collocation":"use grassland","example":"I can use grassland."},{"word":"hunt","ipa":"hʌnt","meaning":"打猎；狩猎;搜索；搜寻;狩猎区域;狩猎队;狩猎者;","collocation":"use hunt","example":"I can use hunt."}],"patterns":[{"name":"Do you have","examples":["Do you have an eraser？","Do you have basketball?Let's play together!"],"translations":["你有一个大脑袋吗？"]},{"name":"Where does(第三人称单数)","examples":["Where does  the horse live?","Where does he want to go?"],"translations":["狮子住在哪里？"]},{"name":"Do you like to","examples":["Do you like to share your twist car with other little friends？","Do you like to eat vegetables."],"translations":["你喜欢吃肉吗？"]}],"dialogueTranslations":["吼！大家好，今天我们要看一种动物。","它叫老虎。老虎，老虎，老虎。吼！","老虎是什么颜色的？","老虎是黄色的，有黑色的条纹。","额头和脸颊上都有黑色条纹。吼！","在哪里可以看到老虎？","嗯，我想你可以在动物园看到老虎。","是的，我可以在动物园看到老虎。","老虎很凶猛。老虎可以生活在森林里。","它是森林之王。","老虎，老虎，吼。"]},{"number":4,"name":"Tiger","image":"assets/noun-cards/004.jpeg","imageOk":true,"dialogue":"亲子对话       \nRoar！Hi everyone.Today is a roaring animal.\nIt's called a tiger.Tiger,tiger,tiger.Roar!\nWhat color is a tiger?\nThe tiger is yellow with black stripes.\nBlack stripes on his forehead, on his cheeks.Roar!\nWhere can you see a tiger?\nEn. I think you can see a tiger in the zoo.\nYes, I can see a tiger in the zoo.\nAnd the tiger is very fierce. Tigers can live in the forest.\nAnd it's the king of the forest.\nTiger tiger,roar.","translation":"这段亲子对话围绕“Tiger”展开，可结合图片逐句理解和跟读。","words":[{"word":"roaring","ipa":"ˈrɔːrɪŋ","meaning":"吼叫（声）；咆哮（声）;大喊；大叫；喧嚷；咆哮;（马的）吼喘症，喘鸣症;","collocation":"use roaring","example":"I can use roaring.","sourceExample":"Their new album is a rip-roaring corker.","sourceTranslation":"他们的新专辑非常棒。"},{"word":"stripe","ipa":"straɪp","meaning":"条纹；线条;条纹布；条纹织物;条状花纹；条纹;（尤指军装上表示军阶的）条纹，条纹标志;类型；类别;抽打；鞭打;","collocation":"use stripe","example":"I can use stripe.","sourceExample":"politicians of every stripe","sourceTranslation":"形形色色的政客"}],"patterns":[{"name":"What color is...","examples":["What color is mom's dress?","What color is baby's hair?"]},{"name":"Where can you...","examples":["Where can you find butterflies?","Where can you see the Northstar?","Where can you feel the comfortable?"]},{"name":"I can...","examples":["I can see a rainbow in the sky!","I can feel cold after the snow."]},{"name":"It is...","examples":["Look! It is a frog!","Listen!It is a bird singing!"]}]},{"number":5,"name":"Monkey","image":"assets/noun-cards/005.jpeg","imageOk":true,"dialogue":"亲子对话       \nHello，little darling.\nToday we are going to look at a very clever animal.\nIt's called a monkey.Monkey.Monkey.Monkey.Monkey.\nWhat color is a monkey?\nA monkey is brown.It's a brown monkey.\nWhat can a monkey do?\nEn. A monkey can climb a tree.\nCan you climb a tree? Mommy can't.\nWhat does the monkey like to eat?\nA monkey likes to eat bananas.A monkey likes bananas.\nAnd a monkey likes peaches. A monkey likes peaches.\nDo you like bananas and peaches too?\nOk, let's read one more time.Monkey.Monkey.","translation":"这段亲子对话围绕“Monkey”展开，可结合图片逐句理解和跟读。","words":[{"word":"peach","ipa":"piːtʃ","meaning":"桃（蔷薇科小乔木）;桃子;桃红色;特别受人喜爱的人（或事物）;","collocation":"use peach","example":"I can use peach."}],"patterns":[{"name":"Is it very ...?Yes/No, it's very ...","examples":["Is it very scary? Yes, it's very scary.","Is it very boring? No, it's very interesting."]},{"name":"What can we do there?I can do sth...","examples":["What can we do here? I can read books in the library.","What can we do there? We can play beachball on the beach."]},{"name":"What are you doing,...?...is doing ...","examples":["What are you doing, daddy? Your daddy is cleaning the bedroom.","What are you doing, mommy? Your mommy is washing her face."]}]},{"number":6,"name":"Panda","image":"assets/noun-cards/006.jpeg","imageOk":false,"dialogue":"亲子对话       \nHello. Little ones.\nToday we are going to look at a panda.\nIt's a very very lovely animal. Panda.Panda.\nP-P-P-an-an-an-da-da-da-panda.\nA panda is very fat.This is a fat panda.\nWhat color is the panda?It's white and black.\nThe panda is white and black.\nWhat does the panda like to eat ?Bamboo.\nA panda likes to eat bamboo.\nDo you like to eat bamboo? No.No...\nYou can't eat bamboo.You can eat vegetables.\nA panda likes bamboo.\nWhere can you see a panda?Go to the zoo.\nWhy not go to the zoo and see the bamboo.","translation":"这段亲子对话围绕“Panda”展开，可结合图片逐句理解和跟读。","words":[{"word":"bamboo","ipa":"bæmˈbuː","meaning":"簕竹属植物（热带和亚热带地区禾本科高大竹类）;竹竿;竹类植物（如北美箭竹属、刚竹属、牡竹属等）;","collocation":"use bamboo","example":"I can use bamboo."}],"patterns":[{"name":"Do you like to do？","examples":["Do you like to draw pictures?","Do you like to shopping？"]},{"name":"You can/can't...","examples":["You can read books. You can't play the game.","You can eat fruits.You can't eat candies."]},{"name":"Where can you..?","examples":["Where can you see an elephant ?","Where can you see flowers?"]},{"name":"Why not ...?","examples":["Why not go to the park and go to see flowers.","Why not go to the concert and go to meet your idol."]},{"name":"This is a...","examples":["This is a cute baby.","This is a beautiful picture."]}]},{"number":7,"name":"Pig","image":"assets/noun-cards/007.jpeg","imageOk":false,"dialogue":"亲子对话       \nHello. Little darlings，\nToday，we are going to look at a very fat animal.\nIt's a pig! Pig Pig Pig.\nA pig says oink oink.\nA pig has a very funny nose.\nA pig has two big ears.\nA pig has four feet like this.\nVery short pig feet.\nThis is a pig.\nWhat color is a pig?\nIt's a pink animal. The pig is pink.","translation":"这段亲子对话围绕“Pig”展开，可结合图片逐句理解和跟读。","words":[{"word":"oink","ipa":"ɔɪŋk","meaning":"哼哼；发呼噜声","collocation":"use oink","example":"I can use oink."}],"patterns":[{"name":"It's a ...","examples":["It's a panda eating bamboo.","It's a airplane in the sky!"]},{"name":"...has a ...","examples":["The elephant has a long trunk.","The baby has a beautful hair."]},{"name":"This is a...","examples":["This is a cute lamb.","This is a hardworking bee."]},{"name":"What color is...?","examples":["What color is the dog?","What color is the moon?"]}]},{"number":8,"name":"Elephant","image":"assets/noun-cards/008.jpeg","imageOk":false,"dialogue":"亲子对话       \nHello. Little ones.\nToday we gonna  look at an animal called elephant.\nWhat color is the elephant?It's grey.\nThe elephant is grey.\nAn elephant has two very big ears.\nAn elephant has two big ears.\nWhat's this?It's the elephant's nose.\nAn elephant's nose is very long.\nAn elephant has a long nose.An elephant has two long teeth.\nThey are called tusks.\nTwo long tusks.\nAn elephant is the biggest animal on land.","translation":"这段亲子对话围绕“Elephant”展开，可结合图片逐句理解和跟读。","words":[{"word":"**tusks**","ipa":"tʌsks","meaning":"(象和某些其他动物的)长牙;","collocation":"use **tusks**","example":"I can use **tusks**."}],"patterns":[{"name":"What color is...?","examples":["What color is the bullon？","What color is the leaf？"]},{"name":"What's this?It's a...","examples":["What‘s this ？It's a umbrella.","What‘s this ？It's a teddybear."]},{"name":"...has/have a...","examples":["Monkeys have a long tail.","The rabbit has two long ears."]},{"name":"...is the biggest...","examples":["The tiger is the biggest animal in the forest.","The ant is the smallest animal  on land."]}]},{"number":9,"name":"Sheep","image":"assets/noun-cards/009.jpeg","imageOk":true,"dialogue":"亲子对话       \nHello little ones. \nToday we're gonna  look at a very useful animal.\nSheep sheep sheep sheep. \nWhat color is the sheep? \nIt's white, yes and no.\nBecause some sheep are black.\nHave you heard of that poem and that goes Baa Baa black sheep，\nhave you any wool? \nYes sir yes sir , three bags full.\nA sheep can be white. \nAnd a sheep can be black. \nWhat does sheep like to eat? Grass.\nA sheep likes to eat grass. Baa Baa. Sheep.","translation":"这段亲子对话围绕“Sheep”展开，可结合图片逐句理解和跟读。","words":[{"word":"wool","ipa":"wʊl","meaning":"毛线；绒线;呢绒；毛料；毛织品；羊毛织物;纤维状物;短而密的鬈发;绵状毛;","collocation":"use wool","example":"I can use wool."}],"patterns":[{"name":"What color is...?","examples":["What color is the horse?","What color is the pencil?"]},{"name":"Have you...*fat ones, skinniy ones, fair ones too.*","examples":["Have you heard of that song and that goes six little ducks I once knew,","Have you lent some  money to me?"]},{"name":"...can be...","examples":["The moon can be circular.","The dog can be gentle."]},{"name":"What does...likes to...           ...likes to ...","examples":["What does the giraffe like to eat? It likes to eat carrots.","What does XiaoJiXiang likes to play?He likes to play toycars."]}]},{"number":10,"name":"Rabbit","image":"assets/noun-cards/010.jpeg","imageOk":false,"dialogue":"亲子对话       \nHello little darlings. \nToday we are going to look at a very cute animal.\nrabbit rabbit rabbit.   \nWhat color is the rabbit?   \nA rabbit can be black, and a rabbit can be white.   \nA rabbit is very cute.  \nA rabbit has two long ears. Very long.   \nDo you have two long ears?\nNo, I have two short ears. What does the rabbit like to eat?\nA rabbit likes to eat carrots and cabbage. \nDo you like carrots? \nUm, that's good. \nA carrot is very good for you.","translation":"这段亲子对话围绕“Rabbit”展开，可结合图片逐句理解和跟读。","words":[{"word":"carrot","ipa":"ˈkærət","meaning":"胡萝卜;诱惑物；诱饵；甜头；好处;","collocation":"use carrot","example":"I can use carrot."}],"patterns":[{"name":"What color is...?","examples":["What color is this bag?","What color are these flowers?"]},{"name":"...can be...","examples":["The sheep can be black.","The cat can be fierce."]},{"name":"...has/have...","examples":["I have a  beautiful mom.","He has a handsome dad."]},{"name":"Do/Does you/he have...?I/He have...","examples":["Do you have some papers? I have some colorful papers.","Does he have a hat? He doesn't ."]},{"name":"：...has/have...","examples":["The mother lion has three little lions.","I have so many books and toys."]},{"name":"What does...likes to...           ...likes to ...","examples":["What does the cat like to eat? It likes to eat fish.","What does XiaoJiXiang like to eat?He likes to eat mush."]},{"name":"Do you like...","examples":["Do you like blueberry cake?","Do you like playing piano？"]}]},{"number":11,"name":"Dog","image":"assets/noun-cards/011.jpeg","imageOk":true,"dialogue":"亲子对话       \nWoof!woof!woof! \nToday we can look at an animal-dog.dog dog dog.\nA dog is very cute . A dog barks. \nSome dogs are very big .Big dogs said barks.\nSome dogs are very small.Small dog is a puppy . \nA puppy said Woof. \nDo you like dogs? I like dogs. \nWhat does the dog like to eat?A bone. \nA dog likes to chew bones.","translation":"这段亲子对话围绕“Dog”展开，可结合图片逐句理解和跟读。","words":[{"word":"bark","ipa":"bɑːk","meaning":"树皮;树皮鞣料；树皮鞣质;吠声；叫声;（人、枪炮等发出的）咆哮声;","collocation":"use bark","example":"I can use bark."},{"word":"chew","ipa":"tʃuː","meaning":"咀嚼;不停地咬；啃;","collocation":"use chew","example":"I can use chew."}],"patterns":[{"name":"... is/are very...","examples":["The baby is very cute.","My friends are very kind."]},{"name":"Do you like...?            I like...","examples":["Do you like ducks? I like ducks.","Do you like to eat vegetables. I like it."]},{"name":"What does ...like to...?           ...likes to...","examples":["What does your son like to eat? He likes to eat  pizza.","What do you like to do? I like to play violin."]}]},{"number":12,"name":"Deer","image":"assets/noun-cards/012.jpeg","imageOk":false,"dialogue":"亲子对话       \nHello dear darling.\nToday we are gonna look at a very beautiful animal.\nIt is a deer.deer.deer.\nLook at this beautiful deer .\nIt is brown and a boy deer has got large antlers. \nA boy deer has  large antlers.\nDo you have antlers? No, I have no antlers. \nI know a very famous reindeer.It's called Rudolph.\nWhat did he do?Let's sing it!\nRudolph, the red-nosed reindeer, had a very shiny nose,\nAnd if you ever saw him，You would even say it glows.","translation":"这段亲子对话围绕“Deer”展开，可结合图片逐句理解和跟读。","words":[{"word":"antler","ipa":"ˈæntlə","meaning":"鹿角；茸角","collocation":"use antler","example":"I can use antler."},{"word":"reindeer","ipa":"ˈreɪnˌdɪə","meaning":"驯鹿（分布于格陵兰岛、欧洲、亚洲和北美洲的寒冷地区）","collocation":"use reindeer","example":"I can use reindeer."},{"word":"glow","ipa":"ɡləʊ","meaning":"（高温物体发出的）红光，火光;灯光；光亮;绚丽；鲜艳;（肤色的）红润，明亮;喜悦；满足感;激情；热情;","collocation":"use glow","example":"I can use glow."}],"patterns":[{"name":"It is a ...","examples":["It is an owl.","It is an orange."]},{"name":"... has a ...","examples":["Sheep has a lot of wool.","Pig has a funny nose."]},{"name":"Do you have...?           I have no...","examples":["Do you have a lot of new clothes? I  have no new clothes.","Do you have a pet? I have no pet."]},{"name":"What did he do?","examples":["What did you do?","What did mother do?"]}]},{"number":13,"name":"Cat","image":"assets/noun-cards/013.jpeg","imageOk":false,"dialogue":"亲子对话       \nHello dear darling.\nToday we are gonna look at a very cute animal-cat.cat.cat.cat.\nA cat says meow meow ,and the cat can purr purr.\nWhat color is cat?\nA cat can be white.yes. A white cat.\nA cat can be black.\nSome cats are black.And some cats are calico. \nA calico cat has stripes on the body，just looks like a little tiger.\nWhat does a cat like to eat? \nThe cat likes to eat fish.\nMeow meow,cat.","translation":"这段亲子对话围绕“Cat”展开，可结合图片逐句理解和跟读。","words":[{"word":"purr","ipa":"pɜː","meaning":"呼噜声；呜呜声;低沉的咕隆声;","collocation":"use purr","example":"I can use purr."},{"word":"calico","ipa":"ˈkælɪˌkəʊ","meaning":"白棉布；本白棉布;印花棉布;","collocation":"use calico","example":"I can use calico."},{"word":"stripe","ipa":"straɪp","meaning":"条纹；线条;条纹布；条纹织物;条状花纹；条纹;（尤指军装上表示军阶的）条纹，条纹标志;类型；类别;抽打；鞭打;","collocation":"use stripe","example":"I can use stripe.","sourceExample":"politicians of every stripe","sourceTranslation":"形形色色的政客"}],"patterns":[{"name":"What color is ...?","examples":["What color is the bird？","What color are your eyes？"]},{"name":"... can be ...","examples":["A bear can be white and black.","The sky can be blue and gold."]},{"name":"looks like a ...","examples":["The  girl  looks like a deer."]},{"name":"What does ... like to ...?","examples":["What does the panda like to eat?","What does your son like to play?"]}]},{"number":14,"name":"Fox","image":"assets/noun-cards/014.jpeg","imageOk":false,"dialogue":"常速语境（名词复述）      \nHello dear darling.Today we are gonna look at very cunning animals.\nIt is a fox.fox.fox.f-o-x.fox. \nLook at the fox.\nA fox has a very very pointy face.\nDo I have a pointy face? No.\nDo you have a pointy face? \nNO, a fox has a pointy face .\nAnd a fox has a  very beautiful bushy tail. \nA very beautiful tail.And it is very big .\nWhere is my tail? \nNO, I have no tail.\nDo you have a tail?\nNo. A fox has a bushy tail.","translation":"这段亲子对话围绕“Fox”展开，可结合图片逐句理解和跟读。","words":[{"word":"cunning","ipa":"ˈkʌnɪŋ","meaning":"狡诈的；狡猾的；诡诈的;聪明的；灵巧的;巧妙的；精巧的；新颖独特的;","collocation":"use cunning","example":"I can use cunning."},{"word":"pointy","ipa":"ˈpɔɪntɪ","meaning":"有尖头的；带尖的；多尖头的","collocation":"use pointy","example":"I can use pointy."},{"word":"bushy","ipa":"ˈbʊʃɪ","meaning":"灌木茂密的;","collocation":"use bushy","example":"I can use bushy."}],"patterns":[{"name":"Do I have...?","examples":["Do I have blue eyes?","Do I have a lot of money?"]},{"name":"Do you have...?","examples":["Do you have gold hair?","Do you have a long nose?"]},{"name":"Where is my...?","examples":["Where is my schoolbay?","Where is my pink dress?"]},{"name":"I have no...","examples":["I have no gold hair.","I have no long nose."]}]},{"number":15,"name":"Penguin","image":"assets/noun-cards/015.jpeg","imageOk":false,"dialogue":"常速语境（名词复述）      \nHello little one.Today we are gonna look at a very cute animal. \nIt's called a penguin.penguin.penguin.\nA penguin is a bird.but,a penguin can not fly. \nA penguin can not fly，eventhough it's a bird. \nA penguin can stand, a penguin can waddle,waddle.waddle.waddle.\nWhere does a penguin live? \nA penguin lives in Antarctica.  Antarctica.\nIt's very cold place.There is ice everywhere.so cold.\nBut penguins are not afraid.","translation":"这段亲子对话围绕“Penguin”展开，可结合图片逐句理解和跟读。","words":[{"word":"Antarctic","ipa":"æn'tɑːktɪkə","meaning":"南极洲","collocation":"use Antarctic","example":"I can use Antarctic."}],"patterns":[{"name":"can do/can not ...","examples":["A bird can fly, can not swing.","A monkey can climb a tree, can not swim."]},{"name":"Where does ... live?","examples":["Where does a lion live? A lion lives on the grassland.","Where does a tiger live? A tiger lives in the forest."]},{"name":"There is...","examples":["What's on the table? There is a book on the table.","There are snakes everywhere."]}]},{"number":16,"name":"Hen","image":"assets/noun-cards/016.jpeg","imageOk":true,"dialogue":"常速语境（名词复述）      \nHello,dear darling.\nToday we are gonna look at a mother animal.  \nWhat's that?         \nIt's a hen.Hen,hen.OK.\nIf she is a mother,then who is the baby?  \nChick! A chick is the hen's baby.  \nHen,chick, hen, chick, hen, chick, hen, chick, hen, chick...  \nHen is the mother, chick is the baby.\nHen,chick, hen, chick, hen, chick, hen, chick, hen, chick...\nAnd hen says, cluck, cluck, cluck...   \nA hen can lay eggs.  \nHow many eggs can a hen lay a day?   \nOne egg a day. Hen, hen.","translation":"这段亲子对话围绕“Hen”展开，可结合图片逐句理解和跟读。","words":[{"word":"cluck","ipa":"klʌk","meaning":"咯咯声;（像母鸡叫的）啧啧声;","collocation":"use cluck","example":"I can use cluck."},{"word":"lay","ipa":"leɪ","meaning":"放置；安放；搁;铺放；铺设;（鸟类）产（卵）；（尤指家鸡）下（蛋）;奠定（基础）；打下（基础）;布置；设计；制订；准备;使处于特定情景；为…设置地点场景;敷上；涂上；施以;将…加诸;押（赌注）；同（某人）打赌;使落下；阻止…扬起;与…上床;赌（马）输掉比赛;压平；把…弄平整;（劈树枝）修筑;搓（股索）成绳；搓编（绳、缆等）;调…至瞄准位置;","collocation":"use lay","example":"I can use lay."}],"patterns":[{"name":"What's that?It's a...","example":"Can you use What's that?It's a... in a sentence?"},{"name":"Who is ...?","example":"Can you use Who is ...? in a sentence?"},{"name":"can do...","example":"Can you use can do... in a sentence?"},{"name":"How many ...can...do?","example":"Can you use How many ...can...do? in a sentence?"}]},{"number":17,"name":"Horse","image":"assets/noun-cards/017.jpeg","imageOk":false,"dialogue":"常速语境（名词复述）      \nHello, dear darling.  \nToday we are gonna look at a very strong animal.  \nIt's a horse. Horse,horse...   \nOK. Let's look at the horse. What color is it? \nIs it a black horse? \nIt can be a black horse.\nDo we have a white horse?   \nEmhm, some horses are white.\n And some horses are brown.   \nAnd a horse can run very fast. \nA horse can run super fast.  \nA horse can run slowly too. \nIt can walk. FAST. \nA horse can run very fast.","translation":"这段亲子对话围绕“Horse”展开，可结合图片逐句理解和跟读。","words":[],"patterns":[{"name":"What color is it?","examples":["What color is a panda?","What color is your dress?"]},{"name":"Is it a ...?","examples":["Is it a table?No , it isn't a table.","Is it a gorilla?No , it isn't a gorilla."]},{"name":"It can be a...","examples":["It can be a green apple.","It can be a black rabbit."]},{"name":"Do we have a...","examples":["Do we have a gametable?","Do we have a calico cat?"]},{"name":"...can do ...","examples":["A rabbit can jump very high.","A snake can slither very slowly."]}]},{"number":18,"name":"Donkey","image":"assets/noun-cards/018.jpeg","imageOk":false,"dialogue":"常速语境（名词复述）      \nHello, dear darling. Today we are gonna look at one very useful animal.   \nIt's a donkey. Donkey, Donkey.   \nWhat does a donkey say?\nA donkey says er-er.   \nA very funny noise right? \nAnd the donkey is gray. \nIt's a gray donkey. \nWhere can you see a donkey?   \nA donkey works on a farm.  \nIt works like this-goes round and round and round.   \nIt helps us a lot.\nLook at the donkey.   \nDo you think it looks like a horse? em.   \nIt looks like a horse. This is a gray donkey.   \nDonkey, Donkey.","translation":"这段亲子对话围绕“Donkey”展开，可结合图片逐句理解和跟读。","words":[{"word":"round","ipa":"raʊnd","meaning":"圆的;球形的;弧形的;圆润的；丰满的;环行的；绕圈的;舍入的；取整数的;完整的；十足的;可观的；大量的;刻画丰满的;（声音）洪亮圆润的;（步伐）轻快的，轻捷的;（讲话）坦率的，率直的;圆唇的；用圆唇发出的;","collocation":"use round","example":"I can use round."}],"patterns":[{"name":"What does a ... say?","examples":["What does a wolf say?","What does an elephant say?"]},{"name":"It's a ...","examples":["It's a green car.","It's an oversize Jacket."]},{"name":"Where can you see a ...?","examples":["Where can you see the aurora？","Where can you see a hippo？"]},{"name":"It looks like a ...","examples":["It looks like a balck monkey.","It looks like a little tiger."]}]},{"number":19,"name":"Bull","image":"assets/noun-cards/019.jpeg","imageOk":true,"dialogue":"常速语境（名词复述）      \nHello everybody. \nToday we are gonna look at a very strong animal. \nIt's a bull. bull, bull.\nWhat color is a bull?   \nIt's brown. A bull is brown.   \nA bull is a boy cow. \nSo can a bull give you milk?   \nNo, a bull is a boy cow. \nWhat can a bull do?  \nIt can help the farmers to plow plow plow.   \nA bull is a very helpful boy cow.   \nWhat does a bull like to eat?  \nA bull likes to eat grass.  \nAnd a bull says moo moo.   \nOK, this is the bull. bull, bull.","translation":"这段亲子对话围绕“Bull”展开，可结合图片逐句理解和跟读。","words":[{"word":"plow","ipa":"plaʊ","meaning":"犁;北斗七星;","collocation":"use plow","example":"I can use plow."}],"patterns":[{"name":"What colour is ...?","examples":["What color is the cat?It's calico cat.","What color is your vest?It's green."]},{"name":"Why is a ...?","examples":["Why is a bad animal?","Why is a poor child?"]},{"name":"It can ...","examples":["It can make a sweater for you.","It can hatch eggs ."]},{"name":"Do you like ...? Yes! I like it!","examples":["Do you like orange juice? Yes ! I like it!","Do you like tomato? No!I hate it!"]}]},{"number":20,"name":"Gorilla","image":"assets/noun-cards/020.jpeg","imageOk":true,"dialogue":"常速语境（名词复述）      \nHello everybody. \nToday we are gonna look at one animal called gorilla.gorilla.\nThe gorilla looks like one other animal that we talked about a monkey. \nA gorilla is a super big monkey. \nA gorilla is bigger than a monkey. \nA gorilla is bigger than a monkey. \ngorilla, monkey, gorilla, monkey, gorilla, monkey. \nOne more time, gorilla, monkey, gorilla, monkey, gorilla, monkey. \nA gorilla is black. It goes woo woo woo woo. \nA gorilla walks on four legs like this. \nA gorilla is very strong.","translation":"这段亲子对话围绕“Gorilla”展开，可结合图片逐句理解和跟读。","words":[],"patterns":[{"name":"... looks like one other...","example":"Can you use ... looks like one other... in a sentence?"},{"name":"A ... is a ...","example":"Can you use A ... is a ... in a sentence?"},{"name":"... is bigger than ...","example":"Can you use ... is bigger than ... in a sentence?"},{"name":"A... do on ...","example":"Can you use A... do on ... in a sentence?"}]},{"number":21,"name":"Owl","image":"assets/noun-cards/021.jpeg","imageOk":false,"dialogue":"常速语境（名词复述）      \nHello, dear darling. Today we are gonna look at one bird,\ncalled:owl owl owl.   \nLook at this owl. An owl has two big eyes.   \nDo you have two big eyes?  \nAn owl has two big eyes.   \nWhy does an owl have two big eyes?   \nBecause an owl is night animal, It comes out at night.   \nSo it stands on the tree, and looks for the mice.   \nWhere are the mice?\nI see one mouse. \nIt's gonna fly and catch it. \nThe owl says\"wu…wu…\" owl owl.","translation":"这段亲子对话围绕“Owl”展开，可结合图片逐句理解和跟读。","words":[],"patterns":[{"name":"What color is...?  It's a ...","examples":["What color is the cup? It's a pink cup.","What color is the sun? It's a red sun."]},{"name":"... going to do...","examples":["I'm going to play tennis with my friends tomorrow.","They're going to the party tonight."]},{"name":"I can see....","examples":["I can see many flowers in the garden.","I can see lots of candies in the bottle."]}]},{"number":22,"name":"Cow","image":"assets/noun-cards/022.jpeg","imageOk":false,"dialogue":"常速语境（名词复述）      \nHello, dear darling.Today we are gonna look at a very good animal.\nIt is called a cow. Cow cow… \nA cow says \"Moo! moo! \" \nIt's a moo moo cow.   \nHey wait a second, I think a moo moo cow looks like some other animal,  \nWe talk about \"A bull\". Cow bull cow bull cow bull…   \nA cow is a girl, a bull is a boy, cow bull…   \nWhat colour is a cow? \nA cow is black and white.   \nWhy is a good animal?   \nBecause it gives you milk.   \nIt can give you milk to drink.   \nDo you like milk? \nYes! I like milk.","translation":"这段亲子对话围绕“Cow”展开，可结合图片逐句理解和跟读。","words":[],"patterns":[{"name":"What colour is ...?","example":"Can you use What colour is ...? in a sentence?"},{"name":"Why is a ...?","example":"Can you use Why is a ...? in a sentence?"},{"name":"It can ...","example":"Can you use It can ... in a sentence?"},{"name":"Do you like ...? Yes! I like it!","example":"Can you use Do you like ...? Yes! I like it! in a sentence?"}]},{"number":23,"name":"Apple","image":"assets/noun-cards/023.jpeg","imageOk":false,"dialogue":"常速语境（名词复述）      \nHello, little one's, Today we are gonna look at one fruit.   \nWhat kind of fruit? \nCan you guess?   \nIt's red outside and yellow inside, and it is very yummy.   \nYes, you are right. It's an apple. Apple apple apple…   \nOk, now, an apple is very yummy. I like apples.   \nDo you like apples?\nThat's great! I like apples too.   \nHow about different ways eating apples?   \nI like apple juice, Yum-yum. Apple juice is very healthy.   \nAnd also we can make apples into apple pie.   \nDo you like apple pies? \nI like apple pie. Ok, apple apple.","translation":"这段亲子对话围绕“Apple”展开，可结合图片逐句理解和跟读。","words":[{"word":"healthy","ipa":"ˈhelθɪ","meaning":"健康的；身体好的;健康的；正常运转的；无病的;有益健康的;健全的；正常的；合理的;运转良好的；繁荣的;相当大的；相当多的;","collocation":"use healthy","example":"I can use healthy."}],"patterns":[{"name":"Do you like to do？","examples":["Do you like to eat hamburgers?","Do you like to drive for a trip  by yourself?"]},{"name":"I like to ...","examples":["I like to drive alone by car.","I like to go to movie by myself."]},{"name":"What's your favorite...?","examples":["What's your favorite animal?","What's your favorite perfume?"]}]},{"number":24,"name":"Orange","image":"assets/noun-cards/024.jpeg","imageOk":false,"dialogue":"常速语境（名词复述）\nHello, little one's, Today we are gonna look at one fruit. \nIt's called orange orange orange orange… \nWhat colour is an orange? \nLet me see. Orange is an orange orange, \nIt's funny, isn't?\nOrange is very juicy. Yes, a lot of juice. \nSo we can use oranges to make orange juice. \nIt will give you enough Vitamin C you need everyday. \nSo why not make some orange juice with mommy? \nAnd when you eat orange, don't forget to peel it. \nCan peel the orange before you eat. \nOk, let's say that again: Orange orange.","translation":"这段亲子对话围绕“Orange”展开，可结合图片逐句理解和跟读。","words":[{"word":"juicy","ipa":"ˈdʒuːsɪ","meaning":"多汁的;有趣而刺激的；绘声绘色的;性感的;有利可图的;","collocation":"use juicy","example":"I can use juicy."},{"word":"peel","ipa":"piːl","meaning":"皮；外皮;（移动烤炉中的面包用的）长柄木铲;（16世纪时英格兰和苏格兰边界上为防御外来入侵而建造的）堡塔，堡寨;","collocation":"use peel","example":"I can use peel."}],"patterns":[{"name":"Who is wearing ...? ... is wearing ...","examples":["Who is tying a bowknot? Sister Zhizhi is tying a bowknot.","Who is wearing a slippers? Grandpa is wearing a slippers."]},{"name":"It's very ... to ...， because it has (no) ....","examples":["It's very comfortable,because it has no shoe heel.","It's very pretty, because it has lace."]},{"name":"... wants to....Let's do sth...","examples":["Your brother wants to ride a bike. Let's ride a bike together.","Sister Tangtang wants to skip rope. Let's skip rope together."]}]},{"number":25,"name":"Watermelon","image":"assets/noun-cards/025.jpeg","imageOk":true,"dialogue":"常速语境（名词复述）\nHello, little one's, Today we are gonna learn a very big fruit.   \nHow big?This big?No! This big? \nYes! It's a watermelon.watermelon.watermelon...  \nWhat colour is a watermelon?  \nIt's green outside and it's red inside, and it's got some black dots.  \nThese are black seeds.  \nCan you eat black seeds? \nNo, you eat the red part.\nIt's very juicy.\nAnd you can make watermelon into watermelon juice. emm,Yummy.\nWatermelon watermelon.","translation":"这段亲子对话围绕“Watermelon”展开，可结合图片逐句理解和跟读。","words":[{"word":"dot","ipa":"dɒt","meaning":"点；小点；小圆点；小斑点;小数点;（网址或电子邮件地址中的）点;（i、j等字母上面的）点，小点;附点;断奏记号;（代表乘号或逻辑合取的）点，小点;（电码中的）点;一点；少量;（女人的）嫁妆，妆奁;","collocation":"use dot","example":"I can use dot."},{"word":"seed","ipa":"siːd","meaning":"种子；籽;种子，种（植物繁殖器官的统称，泛指块茎、孢子、球根等）;根源；萌芽；开端;子孙；后代;种子选手;卵（细胞）;晶种；籽晶;","collocation":"use seed","example":"I can use seed."}],"patterns":[{"name":"What color is ...?","examples":["What color is a badger?","What color is a jellyfish?"]},{"name":"These are...","examples":["These are three squirrels building their house.","These are some young mice eating honey quietly."]},{"name":"Can you ...?","examples":["Can you hang on the branch?","Can you run to 30 miles?"]},{"name":"You can do...","examples":["You can gasp after running an athletic meeting.","You can build a castle with some blocks."]}]},{"number":26,"name":"Grape","image":"assets/noun-cards/026.jpeg","imageOk":false,"dialogue":"常速语境（名词复述）\nHello little ones,\nToday we're going to look at a new kind of fruit.\nIt's called grape.grape...\nHow many grapes can you see here?  \none two three four five six six grapes.\nEn ,one more time. \none two three four five six six grapes.  \nWhat color are grapes?Are they purple?\nYes.But we also have white grapes ,red grapes and green grapes.  \nWhat kind of grapes do you like ? I like green grapes.  \nHow about you ? Ok  \nAnd grapes can be made into grape juice, a yummy sweet.  \nAnd also grapes can be made into wine.  \nYou can not drink wine, your mom can.","translation":"这段亲子对话围绕“Grape”展开，可结合图片逐句理解和跟读。","words":[{"word":"wine","ipa":"waɪn","meaning":"葡萄酒;（用除葡萄以外的水果、花等酿制的）酒;红葡萄酒色；深红色；紫红色;酒一般使人陶醉的东西;（含有药物成分的）发酵葡萄汁;","collocation":"use wine","example":"I can use wine."}],"patterns":[{"name":"How many ... can you see  ?","examples":["How many birds can you see in the air?","How many ducks can you see on the lake?"]},{"name":"What color are ...?Are they ...?","examples":["What color are these peaches?Are they pink?","What color are these bubble gums?Are they colorful?"]},{"name":"What kind of ... do you like  ?","examples":["What kind of fruit do you like?","What kind of  story do you like?"]},{"name":"... can be ...","examples":["Wine can be made from grapes.","This book can be found in the library."]},{"name":"You can not ...","examples":["You can not drive the car, your daddy can.","You can not touch the glass.So dangerous."]}]},{"number":27,"name":"Banana","image":"assets/noun-cards/027.jpeg","imageOk":true,"dialogue":"常速语境（名词复述）\nHello little ones. Today we're going to look at another kind of fruit.  \nIt's called banana.banana.  \nWhat color is the banana?\nIt's yellow. A banana is yellow.  \nHow many bananas can you see here?\nI see 123 three bananas.  \nThree bananas make a bunch of bananas.   \nWhich animal likes to eat bananas? \nA tiger?No. A turtle? No.\nYes,the elephant. An elephant likes to eat bananas.  \nHow about this one? Monkey?  \nA monkey likes to eat bananas too.  \nOK,banana,banana.","translation":"这段亲子对话围绕“Banana”展开，可结合图片逐句理解和跟读。","words":[{"word":"bunch","ipa":"bʌntʃ","meaning":"群；伙;大量;隆起；结节;","collocation":"use bunch","example":"I can use bunch.","sourceExample":"They're just a bunch of leeches cadging off others!","sourceTranslation":"他们只不过是一群伸手向人要这要那的寄生虫！"},{"word":"turtle","ipa":"ˈtɜːtl","meaning":"龟；（尤指）海龟;（拉开拉链即可迅速扬帆的）大三角帆拉链袋;","collocation":"use turtle","example":"I can use turtle."}],"patterns":[{"name":"How many... can you see ?","examples":["How many  grapes can you see on the table?","How many  cards can you see under the bed?"]},{"name":"I see ....","examples":["I see 6 grapes on the table.","I see ten cards under the bed."]},{"name":"Which ...likes to ...?","examples":["Which animals likes to eat carrots?","Which one likes to swim?"]},{"name":"... likes to ...","examples":["A rabbit likes to eat carrots.","XiaoMing likes to play twistcar."]}]},{"number":28,"name":"pear","image":"assets/noun-cards/028.jpeg","imageOk":false,"dialogue":"常速语境（名词复述）\nHello dear darling.\nToday we're going to look at another very juicy fruit.\nIt's called pear pear pear pear pear pear .\nOK , now look at this pear.\nWhat color is it?  \nIt's yellow It's a yellow pear.  \nDo you know the pears also have different colors?  \nThere are red pears, white pears, green pears...  \nPears are very juicy, so you can make pear juice.   \nWhy not ask mom to make one cup of pear juicy for you ?  \nyummy yummy .\nOK, read one more time pear.","translation":"这段亲子对话围绕“pear”展开，可结合图片逐句理解和跟读。","words":[],"patterns":[{"name":"Look at ...","examples":["Look at the plane is flying.","Look at the car is going."]},{"name":"Do you know ...?","examples":["Do you know how to make a cup of  pear juicy?","Do you know the reason why XiaoMing didn't go to school yesterday?"]},{"name":"Why not ... ?","examples":["Why not ask your mom to cook lunch for you?","Why not come to play together?"]}]},{"number":29,"name":"coconut","image":"assets/noun-cards/029.jpeg","imageOk":true,"dialogue":"常速语境（名词复述）\nHello dear darling,  \nToday we're going to look at another very special fruit,\ncalled coconut coconut...  \nOk , now look at the coconut.  \nWhat color is it ?\nIt's brown outside ,it's white inside.\nI have a question.\nKnock knock knock , coconut is so hard.\nHow can we eat it?   \nDo we eat this way? no no no,  \nWe need to cut it and then drink the white juice inside.  \nEmmm, It's so delicious.  \nCoconuts grow on tall trees.\nIt's called a coconut tree  \ncoconut tree coconut tree.  \nDo you like coconuts? Emmm I like coconuts.","translation":"这段亲子对话围绕“coconut”展开，可结合图片逐句理解和跟读。","words":[],"patterns":[{"name":"How can we...?","examples":["Look at the plane is flying.","Look at the car is going."]},{"name":"Do we ...?","examples":["Do you know how to make a cup of  pear juicy?","Do you know the reason why XiaoMing didn't go to school yesterday?"]},{"name":"We need to ...","examples":["Why not ask your mom to cook lunch for you?","Why not come to play together?"]},{"name":"...grow on...","examples":["Do you know how to make a cup of  pear juicy?","Do you know the reason why XiaoMing didn't go to school yesterday?"]},{"name":"Do you like...?","examples":["Why not ask your mom to cook lunch for you?","Why not come to play together?"]}]},{"number":30,"name":"vegetable","image":"assets/noun-cards/030.jpeg","imageOk":true,"dialogue":"常速语境（名词复述）\nHello dear darling，  \nWe've talked about animals ,we've talked about fruits.   \nAnd today we're gonna look at vegetables vegetables vegetables...  \nIf you put a finger here, you can feel your lips vibrating.\nVegetable vegetable vegetable.  \nWhat are vegetables?  \nVegetables are very good for your health.  \nFor example: tomatoes potatoes and carrots,\nThey are all kinds of vegetables.  \nAnd we gonna look at them later.  \nSo,do you like vegetables?  \nI eat a lot vegetables every day.  \nThey are very good .","translation":"这段亲子对话围绕“vegetable”展开，可结合图片逐句理解和跟读。","words":[{"word":"vibrating","ipa":"vaɪˈbreɪtɪŋ","meaning":"*","collocation":"use vibrating","example":"I can use vibrating."}],"patterns":[{"name":"It's ... if you do","examples":["It's better if you put little sugar in the soup.","It's better if you go to sleep now."]},{"name":"Why don't we...?","examples":["Why don't we go to the zoo?","Why don't we watch TV？"]}]},{"number":31,"name":"carrot","image":"assets/noun-cards/031.jpeg","imageOk":false,"dialogue":"常速语境（名词复述）\nHello, little ones!\nToday we're looking at another kind of vegetable.\nIt's a carrot carrot carrot...\nNow look at the carrot. \nWhat color is it?\nUm it's orange.Yes. And it's green，it's got green leaves，it is an orange carrot.\nDo you like carrots?\nUm, I like carrots. \nCarrots are sweet and very good for your body.\nWhich animal likes to eat carrots?\nA cat? no.A rabbit，\nA rabbit likes to eat carrots. \nUm, Why not eat a carrot every day?\nCarrot, carrot.","translation":"这段亲子对话围绕“carrot”展开，可结合图片逐句理解和跟读。","words":[],"patterns":[{"name":"What color is it?It's got ...，it is a...","example":"Can you use What color is it?It's got ...，it is a... in a sentence?"},{"name":"Do you like ...?I like...","example":"Can you use Do you like ...?I like... in a sentence?"},{"name":"Which ...likes to eat...?","example":"Can you use Which ...likes to eat...? in a sentence?"},{"name":"Why not ...?","example":"Can you use Why not ...? in a sentence?"}]},{"number":32,"name":"tamato","image":"assets/noun-cards/032.jpeg","imageOk":true,"dialogue":"常速语境（名词复述）\nHello, dear darling.\nToday we're going look at another type of vegetables.\nIt's called tomato. Tomato, tomato. \nNow look at the tomato.\nOh what? You say it is an apple?\nNo, no, no, it only looks like an apple,but it's a fruit,or maybe a vegetable.\nSomeone says it's a fruit, someone says it's a vegetable.\nHow do you like eating the tomato?\nI like tomato soup.Tomato soup is so delicious.\nWould you like to try some tomato soup?\nTomato soup. Let's drink some tomato soup.\nAnd tomatoes are yummy when you just eat them. \nA tomato is so yummy，Tomato.","translation":"这段亲子对话围绕“tamato”展开，可结合图片逐句理解和跟读。","words":[],"patterns":[{"name":"How do you like eating...? I like ...","example":"Can you use How do you like eating...? I like ... in a sentence?"},{"name":"Would you like to ...?","example":"Can you use Would you like to ...? in a sentence?"}]},{"number":33,"name":"pea","image":"assets/noun-cards/033.jpeg","imageOk":false,"dialogue":"常速语境（名词复述）\nHello,dear darling! \nToday we're going to look at another very yummy kind of vegetable. \nIt's called pea,pea...\nPeas are good for us. Peas are very good for us.\nAnd it's a small round and green vegetable,small round and green. \nAnd it comes in three or four in one pot.\nHave you heard the very famous rhyme，called\"peas pudding hot \"? \nNow let's read it.\n\"Peas pudding hot, Peas pudding cold,Peas pudding in the pot - nine days old.\nSome like it hot, some like it cold, some like it in the pot - nine days old.\"\npeas peas...","translation":"这段亲子对话围绕“pea”展开，可结合图片逐句理解和跟读。","words":[{"word":"pot","ipa":"pɒt","meaning":"（长柄有盖的）深平底锅;壶；茶壶；咖啡壶;一壶的量;花盆;（尤指婴幼儿用的）便盆，尿盆;手工陶器;大杯子;装啤酒的容器；啤酒杯;（尤指银质）奖杯;（尤指扑克牌游戏中赌池中的）赌注总额，全部赌注;捕鱼篓；捕虾笼；捕蟹篓;使球入袋的一击;（为特定目的而设的）公共基金;壶穴；锅穴；瓯穴;大麻;","collocation":"use pot","example":"I can use pot."},{"word":"rhyme","ipa":"raɪm","meaning":"韵；押韵;同韵词；押韵词；押韵的诗行;押韵诗；韵文;","collocation":"use rhyme","example":"I can use rhyme."},{"word":"pudding","ipa":"ˈpʊdɪŋ","meaning":"布丁;（一顿饭中的）甜点;布丁（用油酥面团或面糊等做成，松软味咸）;血香肠；黑香肠;布丁（巧克力或水果味的厚奶油状甜点）;","collocation":"use pudding","example":"I can use pudding."}],"patterns":[{"name":"It's a ...and ...sth","example":"Can you use It's a ...and ...sth in a sentence?"},{"name":"Have you did...?","example":"Can you use Have you did...? in a sentence?"}]},{"number":34,"name":"potato","image":"assets/noun-cards/034.jpeg","imageOk":false,"dialogue":"常速语境（名词复述）\nOne potato two potato. \nThree potato four. \nFive potato six potato.Seven potato more.\nHello, dear darling. \nToday we're going to look at a very yummy kind of vegetable,it's called potato,Potato...\nLook at the potato.\nWhat color is it?\nIt's brown on the outside，And it's yellow inside,so yummy，\nAnd it's yummier if you make potatoes into potato chips，\nPotato chips are crispy, crunch crunch，OK\nWhy don't we read that cute rhyme one more time.\n\"One potato two potato. Three potato four. Five potato six potato.Seven potato more\"","translation":"这段亲子对话围绕“potato”展开，可结合图片逐句理解和跟读。","words":[{"word":"chip","ipa":"tʃɪp","meaning":"炸薯条;薯片;食物薄片;（小）片；（小）块;缺口；缺损处;芯片;筹码;（讨价还价的）筹码;传高球；短切球;编织条（用于编织帽子、篮子等的细木条或稻草）;薄木片制扁篮（用于盛放软水果）;","collocation":"use chip","example":"I can use chip."},{"word":"crispy","ipa":"ˈkrɪspɪ","meaning":"脆的；酥脆的；脆生的;（头发）拳曲的，带波浪的;","collocation":"use crispy","example":"I can use crispy."},{"word":"crunch","ipa":"krʌntʃ","meaning":"嘎吱嘎吱地嚼;使发出嘎吱嘎吱的声音;把…压碎；把…揉成一团;","collocation":"use crunch","example":"I can use crunch."}],"patterns":[{"name":"It's ... if you do","example":"Can you use It's ... if you do in a sentence?"},{"name":"Why don't we...?","example":"Can you use Why don't we...? in a sentence?"}]},{"number":35,"name":"fish","image":"assets/noun-cards/035.jpeg","imageOk":false,"dialogue":"常速语境（名词复述）\nHi, dear darling. I have a question for you.\nWhich animal can swim in the water?\nFish.Fish can swim in the water. A fish can swim. \nOkay, now, look at the fish.\nWhat color is this fish?It's blue.\nUm, but fish come in different colors.\nThere are red fish, blue fish, yellow fish, all kinds of colors.\nAnd some fish are big, some fish are small.\nWhich animal likes to eat fish?\nLet me think. A dog?No, no, no, a cat.\nCats likes to eat fish.Cats like to eat fish.\nDo you like to eat fish?Yumm,yumm.\nYes,I like.","translation":"这段亲子对话围绕“fish”展开，可结合图片逐句理解和跟读。","words":[],"patterns":[{"name":"What can you see...?          I can see... doing ...","examples":["What can you see in the garden? I can see many butterflies flying  in the garden.","What can you see in the sky? I can see lots of clouds in the sky."]},{"name":"I'm gonna do sth...","examples":["I'm gonna buy some apples in the supermarket.","I'm gonna fly the kite in the park."]},{"name":"There are sth in the...","examples":["There are 5 spots on the ladybug's back.","There are some stripes on the tiger's body."]}]},{"number":36,"name":"egg","image":"assets/noun-cards/036.jpeg","imageOk":true,"dialogue":"常速语境（名词复述）\nHi,dear darling.\nDo you know what is Susan likes to eat?  \nThe egg.OK. Now let's read it.  \nLook at the egg.  \nWhat color is it? \nIt's got something white.  \nIt's called egg white. It's yummy.\nAnd it's got some yellow.It's called yolk.It's yummy too. \nAnd egg is just so yummy .  \nDo you remember which animal can lay an egg?  \nIt's the hen. Hen, Egg.\nA hen can lay eggs. A hen can lay eggs.\nThere is a famous rhyme called,\nMy black hen.She lays eggs for gentlemen. \nEgg, Hen.","translation":"这段亲子对话围绕“egg”展开，可结合图片逐句理解和跟读。","words":[{"word":"yolk","ipa":"jəʊk","meaning":"蛋黄","collocation":"use yolk","example":"I can use yolk."}],"patterns":[{"name":"Do you know what ...likes to do?","examples":["Do you know what  XiaoJiXiang likes to play?","Do you know what monkeys like to do?"]},{"name":"Do you remember which ... can do sth?","examples":["Do you remember which animal can climb trees?","Do you remember which whale can eat people?"]},{"name":"A ... can do sth","examples":["A parrot can mimic people talking.","A rabbit can hop very far."]}]},{"number":37,"name":"hamburger","image":"assets/noun-cards/037.jpeg","imageOk":true,"dialogue":"常速语境（名词复述）\nHello,dear darling.\nLook at this.It's so yummy.\nIt's called a hamburger hamburger...\nA hamburger is so yummy. \nIt's a fast food.\nIt's very easy to make. \nLook at the hamburger.\nIt's got two pieces of bread. And then there are some vegetables, some cheese and a piece of meat.\nEmmm, It's so delicious.  \nWhere can you buy a hamburger? \nKFC、McDonald and burger king. \nThere are all kinds of hamburgers. There are fish burger、cheese burger 、chicken hamburger、beef burger.\nWhat's your favorite?  \nI like all kind of hamburgers.\nHamburger.","translation":"这段亲子对话围绕“hamburger”展开，可结合图片逐句理解和跟读。","words":[],"patterns":[{"name":"It's very easy ...","examples":["It's very easy for me to make a cake.","It's very easy for you to get 100 points."]},{"name":"there are ...and ...","examples":["There are red flowers, yellow flowers and white flowers in the garden.","There are monkeys, elephants,penguins,zebras and bears at the zoo."]},{"name":"Where can you...?","examples":["Where can you see the dolphin?","Where can you see the famous picture？"]},{"name":"What's your favorite? I like ...","examples":["What's your favorite animal? I like squirrels.","What's your favorite drink? I like apple juice."]}]},{"number":38,"name":"noodles","image":"assets/noun-cards/038.jpeg","imageOk":true,"dialogue":"常速语境（名词复述）\nHello,dear darling.\nToday I'm so hungry. What should I do?  \nEat some noodles. Good idea. noodles，noodles  \nNow look at the noodles.They are so long.  \nHow can I eat noodles? \nUse the chopsticks. \nYes , we Chinese people use chopsticks .\nAnd you use the fork to eat Italian noodles.\nWe call it \"pasta\".En yummy yummy.\nI like chicken noodles、beef noodles,tomato and egg noodles. \nAll kinds of noodles , they are so yummy .  \nWhat type of noodles do you like best?\nI know , it's mommy's noodles . Right?\nNoodles noodles .","translation":"这段亲子对话围绕“noodles”展开，可结合图片逐句理解和跟读。","words":[{"word":"chopsticks","ipa":"ˈtʃɒpstɪks","meaning":"筷子;","collocation":"use chopsticks","example":"I can use chopsticks."}],"patterns":[{"name":"How can I do sth?","examples":["How can I eat soup?","How can I ride a bike?"]},{"name":"I like sth","examples":["I like playing football,playing basketballand tennis.","I like  carrots, peas and  tomatoes."]},{"name":"What type of ... do you like best?","examples":["What type of fast food do you like best?","What type of sport do you like best?"]}]},{"number":39,"name":"candy","image":"assets/noun-cards/039.jpeg","imageOk":false,"dialogue":"常速语境（名词复述）\nMom, I want candy. Have you said that to mommy before?\nThis is candy...\nEr, candy is so sweet . All children love candy.\nBut you can not eat too much candy. Because candy is bad for your teeth.\nCandy is bad for your teeth and for your body.\nWhat are some common type of candy ?\nLooking at this book .Candy house.Look this page .Wow so much candy ,\nThis is a gummy bear . This is sugar cane. This is an orange slice. \nSo much candy.","translation":"这段亲子对话围绕“candy”展开，可结合图片逐句理解和跟读。","words":[{"word":"common","ipa":"ˈkɒmən","meaning":"常见的；普通的；一般的;流行的；普遍的;（二人或多人）共用的，共有的，共同的;（一个或多个国家、社会等的成员）共有的，共同的;低级的；粗俗的；粗鲁的;通常的；起码的;普通的;无特殊地位的；无特权的；普通的;公的;长短共通的；重读或非重读均可的;普通的；通性的;由分支组成的；分出分支的;总的;（天主教弥撒或日课的）常规部分的;","collocation":"use common","example":"I can use common."},{"word":"gummy","ipa":"ˈɡʌmɪ","meaning":"南极星鲨，白斑星鲨（小型鲨鱼，食甲壳动物）;门牙已掉的老母羊;","collocation":"use gummy","example":"I can use gummy."},{"word":"cane","ipa":"keɪn","meaning":"（竹子、藤等植物的）茎秆;茎秆植物;（用于编织篮子、椅子等的）植物茎秆，藤条，竹条，芦秆;（芦苇、葡萄藤等植物的）主茎;硬秆草；（尤指产于美国东南部的）巨北美箭竹;笞杖；笞条;拐杖;雌鼬鼠;","collocation":"use cane","example":"I can use cane."},{"word":"slice","ipa":"slaɪs","meaning":"一份；一部分;（烹饪用）薄刃刀，抹刀;（球的）侧旋;斜击；曲打;削球；斜切球；侧旋球;","collocation":"use slice","example":"I can use slice."}],"patterns":[{"name":"Have you did ...?","examples":["Have you said that you want to watch the star TV show to your mom?","Have you ridden a bike?"]},{"name":"You can not do sth","examples":["You can not overeat.","You can not drive a racing car."]},{"name":"sth is bad for ...","examples":["Eat toomuch fastfood is bad for your health.","Eat toomuch cake is bad for your skin."]},{"name":"What are some common type of ... ?","examples":["What are some common type of coffee?","What are some common type of fastfood?"]}]},{"number":40,"name":"juicy","image":"assets/noun-cards/040.jpeg","imageOk":false,"dialogue":"常速语境（名词复述）\nHello , dear darling.\nToday we are going to look some delicious things to drink .\nJuice juice juice juice juice juice juice. \nOK.everybody.Do you like to drink juice?  \nYes , I like to drink juice.\nWhat's your favorite type of juice? Let me see .  \nHow about apple juice? Er , apple juice is delicious. I like apple juice .  \nWhat about watermelon juice?   \nI like watermelon juice .\nHow about pear juice ? Delicious . I like pear juice .  \nHow about hamburger juice? EW EW EW yukky.","translation":"这段亲子对话围绕“juicy”展开，可结合图片逐句理解和跟读。","words":[{"word":"yukky","ipa":"","meaning":"令人讨厌的","collocation":"use yukky","example":"I can use yukky."}],"patterns":[{"name":"Do you like to do？","example":"Can you use Do you like to do？ in a sentence?"},{"name":"I like to ...","example":"Can you use I like to ... in a sentence?"},{"name":"What's your favorite...?","example":"Can you use What's your favorite...? in a sentence?"}]},{"number":41,"name":"mom","image":"assets/noun-cards/041.jpeg","imageOk":false,"dialogue":"常速语境（名词复述）\nHi dear darling, who is this?\nShe is mommy. She is your mom, mom, mom.\nMom can also be called mommy.\nYour mom love you so much,and you love your mommy too.\nYou can say:Mom, I love you!You can give your mom a kiss on the face.\nWhat did you do with your mom every day?\nDo you eat together?You can say: Mom!Let's eat!\nDo you play together?You can say: Mom!Play with me!\nAnd you can read books with mommy.You can say:Mommy!I want to read books with you.\nAnd don't forget to give your mom a kiss every day.","translation":"这段亲子对话围绕“mom”展开，可结合图片逐句理解和跟读。","words":[],"patterns":[{"name":"Who is wearing ...?","examples":["Who is wearing a vest?Grandpa is wearing a vest.","Who is wearing jeans? Mom is wearing a jeans."]},{"name":"This is a ...Such a ...","examples":["This is a lovely baby.Such a lovely baby.","He is a clever boy.Such a clever boy."]},{"name":"Do you like to do sth?","examples":["Do you like to play table tennis?Yes, I like to play table tennis.","Do you like to wear jackets?No, I don't like to wear jackets."]}]},{"number":42,"name":"Dad","image":"assets/noun-cards/042.jpeg","imageOk":false,"dialogue":"常速语境（名词复述）\nHello , dear darling.\nWho is this.He is daddy.Dad,dad.Dad is your daddy.\nNow let's think about daddy. Emm. Dad is very tall, and you are very short.\nSo, my daddy is tall.Your daddy is very strong,your daddy has big muscles.\nSo, your daddy is very strong.\nWhat's this? mustache, your daddy has mustache.\nSo your daddy has to shave every day.\nWhat does daddy do every day?\nHe goes to work earlymorning and comeback home late.\nSo if you miss your daddy,you gonna say :Come back home soon! I love you daddy!","translation":"这段亲子对话围绕“Dad”展开，可结合图片逐句理解和跟读。","words":[{"word":"mustache","ipa":"məˈstɑːʃ","meaning":"胡子;(很长时称作 moustaches)髭，口上须，八字须;","collocation":"use mustache","example":"I can use mustache."},{"word":"shave","ipa":"ʃeɪv","meaning":"剃去，刮掉（毛发）;刨；削平;把…削成薄片;掠过；擦过;（少量）削减，缩减；使（略为）下降;杀价买进;","collocation":"use shave","example":"I can use shave."}],"patterns":[{"name":"...is tall","examples":["The giraff is tall, the penguin is short.","The boy  is tall, the girl is short."]},{"name":"somebody has sth...","examples":["My mom has lots of new dresses.","XiaoJiXiang has lots of toy cars."]},{"name":"somebody has to do...","examples":["My mom has to clean the house every day.","My dad has to go to work."]},{"name":"What does .... do ? ... does ...","examples":["What does the monkey likes to do? The monkey likes to climb trees.","What does your friend do with you on the weekend? We are going to watch movies and go shopping together this weekend."]}]},{"number":43,"name":"Grandma","image":"assets/noun-cards/043.jpeg","imageOk":false,"dialogue":"常速语境（名词复述）\nHello , dear darling.\nWho is this？This is your grandma,grandma,grandma.\nHow many grandmas do you have?\nDo you know you have two grandmas？\nOne grandma is your mommy's mommy, the other grandma is your daddy's mommy.\nThey are both your grandmas, and both your grandmas love you so much.\nWhat do you do with grandma every day?\nEmmm, grandma loves to go to the supermarket to go shopping.\nYou can shop vegetables together and  grandmas love to dance.\nThey dance beautifully in the park.My grandma loves to dance.\nAnd your grandma love to tell you storys. Take you here and there.\nI love my grandma so much.\nDo you love your grandma？","translation":"这段亲子对话围绕“Grandma”展开，可结合图片逐句理解和跟读。","words":[],"patterns":[{"name":"What am I doing?         I'm doing sth","examples":["What am I doing? I'm washing my hands.","What am I doing? I'm digging a hole on the beach."]},{"name":"What can you see ...? I see....","examples":["What can you see through the window?I see many kids in the playgroud.","What can you see in the garden?I see many red roses."]},{"name":"Who like to do sth?","examples":["Who like to walk in the park?","Who like to play game?"]},{"name":"I want to do sth","examples":["I want to buy new clothes this weekend.","I want to go to the seaside."]},{"name":"No fighting!","examples":["No smoking!","No speaking!"]},{"name":"must do sth,let's do sth","examples":["You must wash your hands before the dinner,let's wash hands.","You must brush your teeth before go to bed, let's brush teeth."]}]},{"number":44,"name":"Grandpa","image":"assets/noun-cards/044.jpeg","imageOk":false,"dialogue":"常速语境（名词复述）\nHello , dear darling.\nToday we are gonna look at a very lovely famliy member grandpa.\nGrandpa. grandpa. grandpa. grandpa.\nLook at this grandpa. He has gray hair. My grandpa has gray hair.\nBecause your grandpa is old, your grandpa has mustache too.\nYour grandpa has gray mustache.\nOk, do you know that you have two grandpas too?\nOne is your mommy's daddy, the other one is daddy's daddy.\nAnd the both grandpas love you.You love both grandpas too.\nDon't forget to say: I love you ! grandpa！\nHe will be very happy.","translation":"这段亲子对话围绕“Grandpa”展开，可结合图片逐句理解和跟读。","words":[{"word":"mustache","ipa":"məˈstɑːʃ","meaning":"胡子;(很长时称作 moustaches)髭，口上须，八字须;","collocation":"use mustache","example":"I can use mustache."}],"patterns":[{"name":"Who is wearing ... today?... is wearing a ...","examples":["Who is wearing a sunhat today? My mom is wearing a sunhat.","Who is wearing sandles today? My dad is wearing a sandles."]},{"name":"What color is...?It's a ...","examples":["What color is your sunhat?It's a pink sunhat.","What color are your sandles?It's blue sandles."]},{"name":"What's your favorite ...?My favorite is...","examples":["What's your favorite fruit? My favorite fruit is apple.","What's your favorite vegetable? My favorite vegetable is eggplant."]}]},{"number":45,"name":"Girl","image":"assets/noun-cards/045.jpeg","imageOk":false,"dialogue":"常速语境（名词复述）\nHello , dear darling.\nI have a question for you. Are you a girl?or a boy?\nOh, you are a girl. I'm a girl too.\nNow, look at this girl. She has long hair.\nUsually, a girl has long hair. And she can tie a  ponytail.\nAnd girl likes wear a dress,a girl has many dresses,beautiful dresses.\nI like to wear beautiful dress.Do you like wear beautiful dress?\nEmm, I believe you do.\nAnd the girl has beautiful names,elsa is girl's name,snowwhite is girl's name.\nAnd Jasmine is a girl's name.\nWhat's your name?girl.","translation":"这段亲子对话围绕“Girl”展开，可结合图片逐句理解和跟读。","words":[{"word":"tie","ipa":"taɪ","meaning":"系；捆；绑;将…捆绑；将…绑住;绑好；捆住；系住;系；拴；扎;系好;连接；联系;限制；束缚;使结为夫妻;将（两个相邻的相同音符）演奏为一个音;用延音连接线连接（两个音符）;","collocation":"use tie","example":"I can use tie.","sourceExample":"It was a white-tie affair.","sourceTranslation":"这是个穿晚礼服的聚会。"},{"word":"ponytail","ipa":"ˈpəʊnɪˌteɪl","meaning":"马尾辫","collocation":"use ponytail","example":"I can use ponytail.","sourceExample":"He's got a ponytail.","sourceTranslation":"他扎了个马尾辫。"}],"patterns":[{"name":"I can use ... to do sth...","examples":["I can use a hair dryer to blow my wet hair.","I can use a spade to dig a hole and use the bucket to fill up sand."]},{"name":"Who can use ...?Can you use ...?","examples":["Who can use the shovel?Can you use the shovel?","Who can use the sweeping robot?Can you use the sweeping robot?"]},{"name":"Can ...use ...? No, it's ...","examples":["Can the little boy use an electric saw?No ,it's too dangerous.","Can the little girl use an electric drill?No,it's also too dangerous."]}]},{"number":46,"name":"Boy","image":"assets/noun-cards/046.jpeg","imageOk":true,"dialogue":"常速语境（名词复述）\n Hello , dear darling.  \n Today we are gonna look at a boy.  \n Are you a boy？  \n Oh yes, you are a boy.That's good.  \n Now let's read this, boy boy...   \n Now look at this boy,  \n Does he have a long hair or short hair?  \n Short hair, yes, a boy has short hair,and he has no mustache.  \n A boy has no mustache.\nYou only grow mustache when you grow up.\n What does the boy like to play?  \n Du Du Du toy guns and Bi bi bi a toy cars.Wu wu wu toy airplane.  \n And who is the very cool boy?  \n Andy is the cool boy, Harry Potter is the cool boy and Jason is a good boy's name.  \n Are you a boy?  \n What is your name?","translation":"这段亲子对话围绕“Boy”展开，可结合图片逐句理解和跟读。","words":[],"patterns":[{"name":"What can you see? I can see ...","examples":["What can you see?I can see 3 birds flying in the sky.","What can you see?I can see a snail crawling."]},{"name":"Do you like ...?I do.          ...make me really ...","examples":["Do you like sunglass?I do. That makes me really cool.","Do you like dress?I do. That makes me really cute."]},{"name":"Somebody likes ...","examples":["My grandma likes dress.Look,my grandma is wearing a red dress.","My dad likes tie. Look, my dad is wearing a blue tie."]},{"name":"Why not do sth?","examples":["Why not spaddle with us?","Why not go to the supermarket?"]}]},{"number":47,"name":"Baby","image":"assets/noun-cards/047.jpeg","imageOk":true,"dialogue":"常速语境（名词复述）\nWa wa wa ，oh What is that? \nA baby.\nA baby is crying , look this, this is a baby, baby baby...\nA baby is so small. A baby is so cute.\nA baby has too very small hands and a baby has too very small feet.\nSmall hands , small feet...And a baby likes to cry a lot.\nWhen a baby is hungry, the baby cries,wu wu wu...\nWhen the baby misses mommy, she cries,wu wu wu...\nBut the baby loves to when the baby sees mommy, a baby will laugh.","translation":"这段亲子对话围绕“Baby”展开，可结合图片逐句理解和跟读。","words":[],"patterns":[{"name":"It is doing ...          I want to do sth...","examples":["It is snowing. I want to build a snowman.","A typhoon is coming, I want to go home now."]},{"name":"What can .... do?  You can do sth...","examples":["What can your rain boots do? It can keep your feet dry.","What can a plane do? It can take you to everywhere."]},{"name":"I am (not) afraid of ....","examples":["I'm afraid of spiders.","I'm not afraid of the typhoon."]},{"name":"I love sth... I use sth...","examples":["I love my piggy balloon. I use balloons to socialize with my friends.","I love my toyguns,I use a toygun to mimic a policeman."]}]},{"number":48,"name":"Robot","image":"assets/noun-cards/048.jpeg","imageOk":true,"dialogue":"常速语境（名词复述）\nHello dear darling,what's this?  \nIt's a robot, robot robot robot...\nI have a robot at home.  \nDo you have a robot at home?  \nOk now,what can a robot do?  \nA robot can talk. Hello, my name is robot.and a robot can sing a song. \nLet's sing a song,Twinkle Twinkle Little Star.\nAnd robot can walk,en en en.and robot can dance,da da da...  \nOk, can you do a robot dance？  \nLet's say it again, robot robot...","translation":"这段亲子对话围绕“Robot”展开，可结合图片逐句理解和跟读。","words":[],"patterns":[{"name":"I have ...","examples":["I have a big nose.","I have two ears."]},{"name":"Do you have ...?","examples":["Do you have new books?","Do you have a twist car?"]},{"name":"What can sth do?","examples":["What can daddy do?","What can a monkey do?"]},{"name":"Sth can ...","examples":["A penguin can swim in the sea.","A tiger can hunt on the grassland."]}]},{"number":49,"name":"Heart","image":"assets/noun-cards/049.jpeg","imageOk":true,"dialogue":"常速语境（名词复述）\nHello everybody, listen Peng Peng Peng...\nWhat's that?It's your heart beat,look this,this is your body part,heart heart heart...  \nWhere's your heart? It's right here inside your chest,and pumps blood in your body,because peng peng peng your heart beats.  \nOk now, look at this heart. It's a shape, it's a beautiful shape.\nA heart shape means love.  \nDo you want to say love to somebody? Yes mom. I love you mom.\nYou can show a heart and you can also show a heart to daddy. I love you daddy.  \nWho do you love?","translation":"这段亲子对话围绕“Heart”展开，可结合图片逐句理解和跟读。","words":[{"word":"chest","ipa":"tʃest","meaning":"胸部；胸膛;箱子;一箱；一箱的量;金库;（金库中的）资金;密封室;","collocation":"use chest","example":"I can use chest.","sourceExample":"His chest was swathed in bandages.","sourceTranslation":"他的胸部裹着绷带。"},{"word":"pump","ipa":"pʌmp","meaning":"（运动时穿的）橡胶底帆布鞋;（尤指跳舞时穿的）无带浅帮矮跟鞋;平底无带女鞋;（常指擦得光亮的）男士正装鞋;抽；吸;泵;","collocation":"use pump","example":"I can use pump.","sourceExample":"Boyle evacuated the chamber of the air pump.","sourceTranslation":"博伊尔抽空了气泵的气室。"},{"word":"beat","ipa":"biːt","meaning":"敲击；击打;敲击声；击打声;节拍；拍子；拍;节奏;巡逻区域；巡逻路线;强节奏的流行音乐（或摇滚音乐）;（两个频率相似的声音或电信号合在一起时产生的）拍;（钟表的擒纵机构对摆轮的）驱动力，作用力;（音步中的）强音，扬音;（帆船的）“之”字形抢风航行;拍打树丛（或草丛）以搜索猎物;（为惊起猎物）对林区有组织的搜索;猎物被惊起的林区;击打;","collocation":"use beat","example":"I can use beat.","sourceExample":"In yesterday's games, Switzerland beat the United States 2–1.","sourceTranslation":"在昨天的比赛中，瑞士队以2比1战胜美国队。"}],"patterns":[{"name":"Where's your...?","examples":["Where's your toy car?","Where's your daddy？"]},{"name":"Do you want to ...?","examples":["Do you want to say thank you to your teacher?","Do you want to go out play with us?"]},{"name":"You can do... and you can also do...","examples":["You can kiss your mom and you can also kiss your daddy.","You can run to home and you can also walk to home."]},{"name":"Who do you ...?","examples":["Who do you like?","Who do you hate?"]}]},{"number":50,"name":"Mouth","image":"assets/noun-cards/050.jpeg","imageOk":true,"dialogue":"常速语境（名词复述）\nHello,little darling,today we are gonna talk about a body parts.\nBut first, I want to guess what it is?  \nIt's on your face,en it's red and it can talk and sing.  \nYou are right,it's your mouth mouth mouth...  \nOk,can you show me your mouth?\nYes, that's your mouth.  \nWhat can a mouth do?  \nYou eat with your mouth, you talk with your mouth.  \nHello mom, and you sing with your mouth, Twinkle twinkle little star...and you kiss your mom with your mouth.","translation":"这段亲子对话围绕“Mouth”展开，可结合图片逐句理解和跟读。","words":[],"patterns":[{"name":"I want to guess ...","examples":["Are you a kind person?","Are you a high school student?"]},{"name":"Can you ...?","examples":["She has a small mouth.","She has a big blue eyes."]},{"name":"What can a ... do?","examples":["What can a baby do?He can smile.","What can a nose do?You smell with your nose."]}]},{"number":51,"name":"Hand","image":"assets/noun-cards/051.jpeg","imageOk":true,"dialogue":"常速语境（名词复述）\nIf you're happy and you know it,clap your hands,clap,clap.\nIf you're happy and you know it,clap your hands,clap,clap.  \nHey,little daring,what are these? These are your hands. \nNow look at this, hand hand hand hand hand.\nRaise your hands. \nHow many hands do you have? I have one,two,two hands. I have two hands. \nWhat can you do with your hands? \nYou can use them to hold things. I hold things with my hands. \nYou shake hands with your new friends. Shake hands. \nYou clap your hands.Let's sing again.  \nIf you're happy and you know it,clap your hands,clap,clap.","translation":"这段亲子对话围绕“Hand”展开，可结合图片逐句理解和跟读。","words":[{"word":"hold","ipa":"həʊld","meaning":"拿着；握住；托住;抱住；拥抱;把…固定住;使保持（某种姿势）;存放;保存;容纳得下;持有；怀有;激发；激起;持有；拥有;进行;考虑；看待;持有;关押；扣留;推迟；延迟；使停住;占领；占据;（为顾客）保留;使保持（在某个价值或水平）;赢得;怀有;持续发出;持有;","collocation":"use hold","example":"I can use hold."}],"patterns":[{"name":"What are these? These are...","examples":["What are these?These are my baby dolls.","What are these?These are my legs."]},{"name":"How many...do you have? I have ...","examples":["How many books do you have? I have one hundres books.","How many ears do you have? I have two ears."]},{"name":"What can you do with ...? I do sth with ...","examples":["What can you do with your ears?I can hear lots of beautiful  sounds  with my ears.","What can you do with your legs?I can walk to everywhere with my legs."]}]},{"number":52,"name":"Feet","image":"assets/noun-cards/052.jpeg","imageOk":true,"dialogue":"常速语境（名词复述）\nIf you're happy and you know it,stomp your feet,stomp,stomp.\nIf you're happy and you know it,stomp your feet,stomp,stomp.\nFeet, everybody. This is your foot.\nOne foot, two feet. I have two feet. I have two big feet.\nDo you have two big feet? No, you have two little feet.Tickle,tickle.\nHow about your mommy and daddy?\nThey have big feet.  \nDoes your daddy have two smelly feet? \nEw,smelly, daddy! Go to wash your feet.\nYou wear shoes on your feet and wear socks on your feet and you stand on your feet.","translation":"这段亲子对话围绕“Feet”展开，可结合图片逐句理解和跟读。","words":[{"word":"tickle","ipa":"ˈtɪkl","meaning":"（用手指）搔…的痒痒，胳肢;使发痒;使高兴；使满足;逗乐；逗笑；使开心；使高兴;用手捉（手抓住鱼的身体、用手指钩住鱼鳃）;","collocation":"use tickle","example":"I can use tickle."}],"patterns":[{"name":"Do you wear ...?No, you wear ...","examples":["Do you wear a dress?No, you wear a skirt.","Do you wear a vest?No, you wear a T-shirt."]},{"name":"Whose ... is this？ It's ...","examples":["Whose juice is this? It's mine.","Whose dress is this? It's my mom's."]},{"name":"Take off your ...","examples":["Take off your clothes.","Take off your T-shirt."]}]},{"number":53,"name":"Leg","image":"assets/noun-cards/053.jpeg","imageOk":true,"dialogue":"常速语境（名词复述）\nHi,dear daring.\nWhat is this? It's your leg. Leg,leg,leg.\nLegs are very long and you have two long legs. \nYou can stand on them. I have two legs.\nWhat is this? A chick. A chick has two legs too.\nHow about a lion?Roar. A lion has one,two,three,four,four legs. \nA lion has four,four legs. Dog?woof. A dog has four legs too. A dog has four legs.\nWhat about fish? Oh!! A fish has no leg. A fish can not walk. OK,leg,leg.","translation":"这段亲子对话围绕“Leg”展开，可结合图片逐句理解和跟读。","words":[],"patterns":[{"name":"sth are very ...  You have ...","example":"Can you use sth are very ...  You have ... in a sentence?"},{"name":"sth has ...","example":"Can you use sth has ... in a sentence?"},{"name":"sth can not ...","example":"Can you use sth can not ... in a sentence?"}]},{"number":54,"name":"Arm","image":"assets/noun-cards/054.jpeg","imageOk":true,"dialogue":"常速语境（名词复述）\nHello,dear daring.\nWhat is this?It is our arms. Arm,arm,arm.  \nHow many arms do you have?One arm, two arms. I have two arms. \nDoes your mommy have two arms too? \nYes,mommy has two arms. Look at our arms. your arms are short. \nA baby has two short arms. How about mommy? \nA mommy has two long arms. \nWhat can you do with your arms? You can stretch your arms, and you can hug with your arms. Hug, hug, mommy. \nSo did you hug your mom with your arms today? Arm,arm.","translation":"这段亲子对话围绕“Arm”展开，可结合图片逐句理解和跟读。","words":[],"patterns":[{"name":"How many ...do you have?","example":"Can you use How many ...do you have? in a sentence?"},{"name":"Does somebody have ...?","example":"Can you use Does somebody have ...? in a sentence?"},{"name":"What can you do with ...? You can ...","example":"Can you use What can you do with ...? You can ... in a sentence?"},{"name":"Did you do sth?","example":"Can you use Did you do sth? in a sentence?"}]},{"number":55,"name":"Building","image":"assets/noun-cards/055.jpeg","imageOk":false,"dialogue":"常速语境（名词复述）\nHello,dear daring. This is a building.building...\nNow look at this building. \nIt is so high.look up. \nHow many floors are there? \nI don't know. Maybe 30 floors.\nl can see so many windows.\nWhat can you see through the windows? \nI see many people.who is this? Grandma.\nWhat is grandma doing in the building? \nGrandma is shopping in the building.Grandma is shopping in the building. \nNow who is this? It is mommy. \nIs mom in the building too?\nYes, Mommy is shopping in the building too.mommy with grandma.And and the boy.\nIs the boy in the building too? \nI think so.building...","translation":"这段亲子对话围绕“Building”展开，可结合图片逐句理解和跟读。","words":[],"patterns":[{"name":"How many floors are there?","example":"Can you use How many floors are there? in a sentence?"},{"name":"What can you see ...? l can see ...","example":"Can you use What can you see ...? l can see ... in a sentence?"},{"name":"What is ...doing in the building?","example":"Can you use What is ...doing in the building? in a sentence?"},{"name":"Is somebody in the building too?","example":"Can you use Is somebody in the building too? in a sentence?"}]},{"number":56,"name":"Bed","image":"assets/noun-cards/056.jpeg","imageOk":true,"dialogue":"常速语境（名词复述）\nHello,dear daring.\nWhat's this? This is a bed....\nNow, look at the bed.\nIs it very soft?Yes, it's very soft.\nAnd what can we do there?\nI can sleep in bed.Oh,Sh...quiet,the baby is sleeping in bed. Sh..quick...\nWhat are you doing, monkey?The monkey is jumping in bed.\nNo,no,no,monkey,stop it,it's dangerous!\nFive little monkeys jump on the bed. One fell off,and bumped his head. \nMama called the doctor,the doctor said,no more monkeys jump on the bed.","translation":"这段亲子对话围绕“Bed”展开，可结合图片逐句理解和跟读。","words":[{"word":"fall off","ipa":"","meaning":"常用词；具体词义见原文","collocation":"use fall off","example":"I can use fall off."},{"word":"bump","ipa":"bʌmp","meaning":"重击；碰撞；撞击力;颠簸；撞击;撞击声；碰撞声；砰的一声;（头上因重击造成的）肿块，包;（路面等的）凸块，隆起;轻微撞车事故;肚子;隆起部分（颅相家认为是能力和性格的象征）;（使飞机向上严重颠簸的）上升气流;（速度比赛中的）相撞，碰撞;","collocation":"use bump","example":"I can use bump."}],"patterns":[{"name":"Is it very ...?Yes/No, it's very ...","example":"Can you use Is it very ...?Yes/No, it's very ... in a sentence?"},{"name":"What can we do there?I can do sth...","example":"Can you use What can we do there?I can do sth... in a sentence?"},{"name":"What are you doing,...?...is doing ...","example":"Can you use What are you doing,...?...is doing ... in a sentence?"}]},{"number":57,"name":"Desk","image":"assets/noun-cards/057.jpeg","imageOk":true,"dialogue":"常速语境（名词复述）\nHello,little one.\nWhat can you see over here?\nOh, it's a desk, desk....\nOkay, now look at the desk.\nWhat can you do with the desk? \nHmm, you can read a book, you can read a book at the desk. \nAnd also,you can study at the desk.\nAnd your daddy can work at the desk in the study,too.\nAnd where else can we see a desk in the classroom?\nLook, I'm in a classroom now,and I can see many, many desks. \nHow many desks can you see? \nOne,two,three,four,five,six,seven,eight,there are eight desks. \nHmm,come in and study with me. desk....","translation":"这段亲子对话围绕“Desk”展开，可结合图片逐句理解和跟读。","words":[],"patterns":[{"name":"What can you do with ...? You can do sth...","examples":["What can you do with your hands? You can cook dinner in the kitchen with your hands.","What can you do with your pen? You can draw a picture with your pen."]},{"name":"Where else can we see ... in ...?  I can see many...","examples":["Where else can you see gorillas in the zoo? I can see so many gorillas in the zoo.","Where else can you see stars in the sky? I can see lots of stars in the sky."]},{"name":"How many ... can you see?","examples":["How many butterflies can you see in the garden?","How many ants can you see on the corner?"]}]},{"number":58,"name":"Table","image":"assets/noun-cards/058.jpeg","imageOk":true,"dialogue":"常速语境（名词复述）\nHello,dear darling.\nThis is a table,table....\nNow, look at the table.\nWhere can you see a table?\nI can see a table in a living room. And I can eat at the table, \nAnd I can read a book at the table, read a book at the table. And you can sit at the table and think.\nWhat's on the table?\nThere is nothing on the table. \nNow, there is candy on the table. Candy on the table. There is candy on the table.\nWhat about now?\nIt is juice on the table, a glass of orange juice, juice on the table. table.","translation":"这段亲子对话围绕“Table”展开，可结合图片逐句理解和跟读。","words":[],"patterns":[{"name":"Where can you see ...?          I can see .... And I can do sth...     *I can see a seesaw in the park.And I can play on the seesaw and fly a  kite in the park.*     *I can see a plane in the sky. And I can go to travel by plane.*","examples":["Where can you see a seesaw?","Where can you see a plane?"]},{"name":"What's on the table? There is/are on the table.","examples":["What's in the sky?There is a plane flying in the sky.","What's in the garden?There are so many butterflies dancing near flowers in the garden."]}]},{"number":59,"name":"Door","image":"assets/noun-cards/059.jpeg","imageOk":true,"dialogue":"常速语境（名词复述）\nKnock,knock,knock.Knock,knock,knock! Hi,little ones,\nWhat am I doing?\nI'm knocking on the door. Look, this is a door,door...\nThis is a brown door, a brown door.\nWhat color is your door?\nHmm, my door is white. Knock,knock,knock!\nOh,I think I can open the door and see what's behind. \nOpen the door. Oh, I see a panda behind the door.Close the door,\nWhat can we see now?\nOpen the door,wow,I see a duck. Quack. Quack. I see a duck behind the door. \nNow open the door. Oh, I see a tiger behind the door. Quick, close the door!\nHum,don't scary. Door...","translation":"这段亲子对话围绕“Door”展开，可结合图片逐句理解和跟读。","words":[],"patterns":[{"name":"What's this? It is a ...         Look at ...","examples":["What's this?It is a moon. Look at the moon ! It looks like a big banana.","What's this?It is a cloud. Look at the cloud !It looks like cotton candy."]},{"name":"What can you do ?You can use sth to do","examples":["What can you do? You can use the pencil to write.","What can you do? You can use the spade to dig a hole."]},{"name":"I did sth..","examples":["I broke my mom's vase yesterday.","I spilled milk on my pillow this morning."]}]},{"number":60,"name":"Window","image":"assets/noun-cards/060.jpeg","imageOk":false,"dialogue":"常速语境（名词复述）\nHello dear darling.\nWhat's this on the card?\nOh,it's a window.window.window...\nCan you see a window in the room?\nOh,there is a window. \nCan you see a window over there?\nYes, there is a window. \nWhy don't we try to open the window and see what you can see outside? \nReady!Open the window,wow,I see a boy playing football outside. \nSo I open the window and see a boy. Now close the window,\nWhat can we see this time? Open the window,I see grandma,a grandma is dancing outside. \nOpen the window,what about now?I see mommy running. \nOpen the window,and you can see the world. window,window.","translation":"这段亲子对话围绕“Window”展开，可结合图片逐句理解和跟读。","words":[],"patterns":[{"name":"Can you see ... in the ...?Yes,there is a ...","examples":["Can you see a  dolphin in the sea?Yes,there are three dolphins jumping on the sea surface.","Can you see a  crab on the beach? Yes,there is a small crab crawling on the beach."]},{"name":"Why don't we try to do sth ?","examples":["Why don't we try to taste the spicy candy?","Why don't we try to catch the small crab and  oberserve it carefully?"]},{"name":"What can we see this time?          Open the ...,I see ... is doing.","examples":["What can we see this time?Open the curtains,I see my baby,my baby is building the sandcastle on the seaside.","What can we see this time?Open the curtains,I see the sunset and afterglow,my mom is takingphoto with the afterglow."]}]},{"number":61,"name":"Sofa","image":"assets/noun-cards/061.jpeg","imageOk":false,"dialogue":"常速语境（名词复述）\nHello dear darling.\nWhat I'm going to talk about today?  \nCan you guess?\nIt's in your living room. It's very big, very soft .\nYou can sit on it and watch TV. \nBingo! It's a sofa...\nLook at this sofa. It's a gray sofa.\nWhat color is your sofa?\nMy soda is brown, I have brown sofa ,Look! \nWho is this?It's a boy.  \nWhat is boy doing?The boy is sitting on the sofa.  \nBanBan,Hello!\nWhat are you doing?\nThe boy is jumping up and down on the sofa. Stop! \nIt's very dangerous,Now the boy jumps off the sofa,\nBut remember it is dangerous ,\nDon't do it. Sit on your sofa.","translation":"这段亲子对话围绕“Sofa”展开，可结合图片逐句理解和跟读。","words":[],"patterns":[{"name":"What I'm going to ...?","examples":["What is he going to do today? He is going to catch the crab and little fish.","What are you going to play now? I'm going to run in the playground."]},{"name":"What color is ...?          ... is..., I have ....","examples":["What color is the whale? The whale is  white.","What color is the crab? The crab is red."]},{"name":"What is ...doing?...is doing sth...","examples":["What is your son doing? He is kicking football with Momo on the seaside."]}]},{"number":62,"name":"Piano","image":"assets/noun-cards/062.jpeg","imageOk":true,"dialogue":"常速语境（名词复述）\nHello,Dear darling ,\nCan you guess what we are talking about today?  \nListen ! it's very big, it's big musical instrument .and you can play it to make music .  \nYes, you are right . It is piano piano...Now look at piano. \nWhat can you see on it?\nI see some white keys.white keys.\nAnd I see some black keys too, black keys ,and you can strike them make a music.\nDuo Re Mi Fa Suo La Si.\nOk,You can play the piano to make beautiful music.\nCan you play the piano?  \nEm…You can try.Let's play the piano.","translation":"这段亲子对话围绕“Piano”展开，可结合图片逐句理解和跟读。","words":[{"word":"musical","ipa":"ˈmjuːzɪkl","meaning":"音乐的；与音乐有关的;有音乐天赋的；热爱音乐的;悦耳的;","collocation":"use musical","example":"I can use musical.","sourceExample":"I'm not musical.","sourceTranslation":"我不通音乐。"},{"word":"instrument","ipa":"ˈɪnstrəmənt","meaning":"器械；器具;乐器;促成因素；实现手段;被他人利用的人；他人的工具;仪器；仪表;（尤指飞机的）导航仪，导航系统;文契;","collocation":"use instrument","example":"I can use instrument.","sourceExample":"Language is an imperfect instrument for conveying thought.","sourceTranslation":"语言是一种表达思想的不完美工具。"},{"word":"strike","ipa":"straɪk","meaning":"打；击；撞;罢工；罢市;打击；袭击；（尤指）空袭;发现;击球未中；好球;（保龄球的）全中;（保龄球全中的）十分;击打声；撞击声;（钟的）打点装置，报时装置;走向;（尤指带来经济收益的）意外成功，完全胜利;","collocation":"use strike","example":"I can use strike.","sourceExample":"Prisoners on hunger-strike were force-fed.","sourceTranslation":"绝食的犯人被强迫进食。"}],"patterns":[{"name":"What can you see ...?I see ...","examples":["What can you see in the seasurface? I see lots of dolphins.","What can you see on the beach? I see lots of  kids and dogs."]},{"name":"Can you ...?         You can ...","examples":["Can you paly the trumpet? You can blow the trumpet to make beautiful music.","Can you build a castle? You can build a sandcastle using the sand."]}]},{"number":63,"name":"TV","image":"assets/noun-cards/063.jpeg","imageOk":false,"dialogue":"常速语境（名词复述）\nHello , dear darling, \nWhat's this?It's a TV...\nDo you like watching TV?\nOf course , I like watching TV. Here is a TV.\nLet's turn it on.\nI like to watch cartoon tv, Here comes daddy.\nHey baby, I want to watch football on TV.\nBut daddy, I'm watching cartoons.\nWhy not watch football together with me?\nLet's watch football together.\nHey you guys, the TV is too loud ,\nturn it down ,sh....too loud, \nDon't watch too much TV,\nOK, mom. We are watching TV now,","translation":"这段亲子对话围绕“TV”展开，可结合图片逐句理解和跟读。","words":[{"word":"cartoon","ipa":"kɑːˈtuːn","meaning":"（报刊上的）连环漫画;动画片；卡通片；动画电影;（壁画、挂毯、镶嵌画等的）草图，底图;","collocation":"use cartoon","example":"I can use cartoon."}],"patterns":[{"name":"Do you like doing sth?          I like doing sth","example":"Can you use Do you like doing sth?          I like doing sth in a sentence?"},{"name":"Why not do sth together with me?","example":"Can you use Why not do sth together with me? in a sentence?"},{"name":"Don't do sth","example":"Can you use Don't do sth in a sentence?"}]},{"number":64,"name":"Freezer","image":"assets/noun-cards/064.jpeg","imageOk":true,"dialogue":"常速语境（名词复述）\nHello dear darling ,\nCan you guess what we are talking about today?\nListen carefully , it's very cold inside，and you put something very cold inside it .\nFor example, ice cream, yogurt，cheese, something that you need in the freezer.\nOk, I know you got it . It's freezer ,freezer, freezer ,so cold inside ...\nWe just said you can put ice cream in it ,\nWhat kind of ice cream do you have in the freezer?\nlet's see. Open the freezer I have apple flavor ice cream in it, banana flavor ice cream,\nyummy...vegetable flavor ice cream, yuck...\nI don't like it.","translation":"这段亲子对话围绕“Freezer”展开，可结合图片逐句理解和跟读。","words":[{"word":"flavor","ipa":"","meaning":"滋味；味道;口味；风味;风格；特色；特点；韵味；氛围;味（用以将夸克区分为上、下、粲、奇、底、顶六类的属性）;","collocation":"use flavor","example":"I can use flavor."}],"patterns":[{"name":"Can you guess what ...","examples":["Can you guess what they are building with blocks?","Can you guess what we are drawing?"]},{"name":"What kind of...do you have...","examples":["What kind of book do you have on your bookshelf?","What kind of dress do you have in your closet?"]},{"name":"I have...","examples":["I have a white dress and a blue dress.","I have a toy car and toy helicopter."]},{"name":"I don't like...","examples":["I don't like carrot-flavored candy.","I don't like black T-shirts."]}]},{"number":65,"name":"Newspaper","image":"assets/noun-cards/065.jpeg","imageOk":true,"dialogue":"常速语境（名词复述）\nWow,oh ,What am I doing?\nI'm reading a newspaper newspaper newspaper...\nEveryone, now look at the newspaper.\nWhat can you see on it? I see pictures, I see words.\nThat's the news , the news can tell us what happenning around us ,\nWho like to read newspaper?\nGrandma says I do. I like to read newspapers. Grandpa says I like to read newspapers too.\nI want to read first !Me first !Me first!No fighting！\nWhy not read newspapers together?\nRemember we must share , let's share, let's read newspapers together.","translation":"这段亲子对话围绕“Newspaper”展开，可结合图片逐句理解和跟读。","words":[],"patterns":[{"name":"What am I doing?","example":"Can you use What am I doing? in a sentence?"},{"name":"What can you see ...? I see....","example":"Can you use What can you see ...? I see.... in a sentence?"},{"name":"Who like to do sth?","example":"Can you use Who like to do sth? in a sentence?"},{"name":"I want to do sth","example":"Can you use I want to do sth in a sentence?"},{"name":"No fighting!","example":"Can you use No fighting! in a sentence?"},{"name":"must do sth,let's do sth","example":"Can you use must do sth,let's do sth in a sentence?"}]},{"number":66,"name":"Envelope","image":"assets/noun-cards/066.jpeg","imageOk":true,"dialogue":"常速语境（名词复述）\nHello,dear darling,\nWhat's this?It's an envelope.\nEnvelope,envelope...\nWhat can you put in an envelope?\nWe can put a letter in an envelope. \nOpen the envelope, put the letter in, and close it. \nYou can put the letter in an envelope. And mail it. Give it to the postman.\nWhat else can we put in an envelope? \nCan you put an elephant in the envelope?\nNo!Because an elephant is so big. \nWhat about the pig?\nNo,no,no.You can't put the pig in an envelope.\nHow about the newspaper?\nEn...that's ok. You can put the newspaper in an envelope.","translation":"这段亲子对话围绕“Envelope”展开，可结合图片逐句理解和跟读。","words":[{"word":"mail","ipa":"meɪl","meaning":"邮政系统；邮递系统;信件；邮包；邮件;（一次接收或递送的）邮件，信件，邮包;邮政列车；邮船；邮政航班;（用金属链环编成的）锁子甲，铠甲;（海龟和龙虾等动物护身的）甲壳;付款；（尤指）租金，税金;谣传；小道消息；（尤指赛马的）内部情报，秘密消息;","collocation":"use mail","example":"I can use mail.","sourceExample":"This system has an electronic-mail facility.","sourceTranslation":"这个系统有电子邮件功能。"},{"word":"postman","ipa":"ˈpəʊstmən","meaning":"邮差；邮递员","collocation":"use postman","example":"I can use postman.","sourceExample":"an elderly, folksy postman","sourceTranslation":"一个为人随和的老邮递员"}],"patterns":[{"name":"What can you do sth?         We can do ...","examples":["What can you build with the sand? I can build an elephant with the sand.","What can you cook for the dinner? I can cook chicken for the dinner."]},{"name":"Can you do sth?         Yes/No! Because ...","examples":["Can you kick the football with your feet? No,because my legs hurt last week.","Can you show your song in the program? Yes,my pleasure."]}]},{"number":67,"name":"Pencil","image":"assets/noun-cards/067.jpeg","imageOk":true,"dialogue":"常速语境（名词复述）\nHello,dear darling,\nWhat can you see over here?\nIt's a pencil...\nLook at the pencil. \nWhat color is it? It's brown. \nIt's a brown pencil.\nWhat can a pencil do ?\nI can write with a pencil, and I can draw with a pencil.\nWhat can you see here?\nI see two pencils.\nWhich pencil do you like? \nDo you like this blue pencil?Do you like wooden pencil?\nEn..I like this pencil.\nBecause this pencil is very beautiful, and it's longer.","translation":"这段亲子对话围绕“Pencil”展开，可结合图片逐句理解和跟读。","words":[{"word":"wooden","ipa":"ˈwʊdn","meaning":"木制的;木头的;呆板的;木讷的;死板的;木头似的;","collocation":"use wooden","example":"I can use wooden."}],"patterns":[{"name":"What can ...do ?         I can do ...  and I can do ...","examples":["What can a desk do? I can eat lunch on the desk,and I can read a book on the desk.","What can a swimsuit do? I can go swimming in a swimsuit.","What can a sunglasses do? I can go to holiday on the seaside with sunglasses."]},{"name":"What can you do here?         I can do ...","examples":["What can you smell over here?I can smell lots of flowers , so fragrant.","What can you hear over here?I can hear a bird singing."]},{"name":"Which ... do you like? Do you like...","examples":["Which butterfly do you like?Do you like the red one?","Which toy car do you like?Do you like the digger?"]},{"name":"I like this ...         Because ... is ....","examples":["I like this red butterfly, because it is very beautiful and it can fly faster.","I like the toy digger, because it's very cool and it is bigger."]}]},{"number":68,"name":"Book","image":"assets/noun-cards/068.jpeg","imageOk":true,"dialogue":"常速语境（名词复述）\nHello,dear darling,\nWhat's this?It's a book, book, book.\nNow, look at the book.\nWhat can you do with a book?\nDo you put a book on your head?No.\nDo you throw your book?No.\nDo you rip your book?\nNo.You need to love your book.Because you can learn many, many things with the helpful book.\nBooks can help you to know the world.\nI love reading books.\nDo you love reading books?\nLook, I've got a blue book.\nWhat's in the book?\nOh, it's a bookmark.It's a piggy bookmark.It's a lion bookmark. \nAnd you can put the bookmark in the book.En..I love the book.\nRead after me:\nI love reading books.","translation":"这段亲子对话围绕“Book”展开，可结合图片逐句理解和跟读。","words":[{"word":"rip","ipa":"rɪp","meaning":"撕；撕裂；划破;撕去；扯掉；剥去;沿纹理锯（或劈开）;非法下载；（对音乐、软件等）盗版;","collocation":"use rip","example":"I can use rip."},{"word":"bookmark","ipa":"ˈbʊkˌmɑːk","meaning":"书签;（网站的）收藏夹，书签;书签;","collocation":"use bookmark","example":"I can use bookmark."}],"patterns":[{"name":"What can you do with...? You can do sth with...","examples":["What can you do with a pencil? You can write a article with a pencil.","What can you do with a paper?You can draw a picture on paper."]},{"name":"Do you do sth ....?","examples":["Do you throw your pencil under the bed?","Do you hide your cartoon book behind the door?"]},{"name":"Sth can do sth to ...","examples":["Mommy can help you to do everything.","Frogs can eat mosquitoes to protect the environment."]},{"name":"Do you love doing sth? I love doing sth.","examples":["Do you love paddling in the sea? I love paddling.","Do you love flying kites? I love flying kites."]},{"name":"I I've got a sth.","examples":["I have got a new shoes.","I have got a new goggles."]},{"name":"What's in/on/under/aroud  the ...? It's a ...","examples":["What's on the seasurface? It's a huge ship.","What's on the grass?So smelly!Eew, It's a poop."]}]},{"number":69,"name":"Ink","image":"assets/noun-cards/069.jpeg","imageOk":true,"dialogue":"常速语境（名词复述）\nHello, dear darling,\nDo you know what this is?\nIs it water in the bottle?\nNo.It's ink.Ink..ink.\nWhat is ink? \nYou put ink in a pen.\nNow, look at these. \nI have two pens.This is the black pen, and this is the red pen.\nSo, this black pen has black ink, and the red pen has red ink. What about a blue pen?\nA blue pen has blue ink. \nCould you do me a favor?\nCould you pass the ink to mummy?\nSure, I'm happy to help.”Hi, mummy, here the ink.” no.no, slow down, be careful. \nNo, I dropped the ink. I spilled the ink.Oh, I'm so sorry, mum.\nI'm so sorry to spilled the ink.","translation":"这段亲子对话围绕“Ink”展开，可结合图片逐句理解和跟读。","words":[{"word":"drop","ipa":"drɒp","meaning":"（一）滴;少量；一点点;滴状物（如坠子）;糖果；硬糖;下降；减少;下降；下落;下降距离；落差；下落距离;陡坡；峭壁;（部队、装备或补给的）空投;秘密传递；秘密递送;藏匿处;入户电缆;（容器上投放物品的）狭缝，狭孔;（舞台上的）垂幕;（主横帆的）帆高;桩门倒下;","collocation":"use drop","example":"I can use drop."},{"word":"spill","ipa":"spɪl","meaning":"溢出；洒出；溢出量;摔下；跌落;职位空缺;（点火用的）木片，纸捻;塞子；销子;","collocation":"use spill","example":"I can use spill."},{"word":"favor","ipa":"","meaning":"帮忙；善举；恩惠;赞许；赞赏；支持;偏爱；偏袒;允许；许可;（常指女子赠与骑士表示忠诚的）徽章，缎带;通信；（尤指）商业信函;容貌；外表;","collocation":"use favor","example":"I can use favor.","sourceExample":"Safire writes hilariously of being banished from presidential favor.","sourceTranslation":"萨菲尔幽默地描写了自己没能博取总统好感的事情。"}],"patterns":[{"name":"Is it ... in ...?","examples":["Is it a bird in the birdhouse?","Is it a penguin on the watersurface?"]},{"name":"I have ....This is... and this is ...","examples":["I have ten fingers.This is my thumb and this is my index finger.","I have two bags.This is my red bag and this is my green bag."]},{"name":"Somebody has ...","examples":["Mommy has lots of dresses.","Spider has eight legs.Camel has one hump."]},{"name":"Could you do sth?","examples":["Could you pass the book to me?","Could you pour milk in the cereal for me?"]},{"name":"I'm so sorry to do sth...","examples":["I'm so sorry to burst your balloon.","I'm so sorry to break your watch."]}]},{"number":70,"name":"Cup","image":"assets/noun-cards/070.jpeg","imageOk":false,"dialogue":"常速语境（名词复述）\nOh,dear little ones.\nWhat am I doing?\nI'm drinking.\nAnd this is my cup.Cup..cup.\nThis is my cup.It is grey. \nDo you have a cup?\nWhat color is your cup? Is it white?\nOh, you have a white cup.\nNow,what's in it?\nCan you guess what is in my cup?\nIs there juice in my cup?\nNo, sorry, there's no juice in my cup. \nIs there milk?\nNo, there is no milk in my cup.\nYeah, there is water in my cup. I'm drinking water with my cup.\nRead after me:\nI drink tea from a cup.","translation":"这段亲子对话围绕“Cup”展开，可结合图片逐句理解和跟读。","words":[],"patterns":[{"name":"What am I doing?I'm doing sth","examples":["What am I doing? I'm drinking apple juice.","What am I doing? I'm mimicking a gorilla beating my chest."]},{"name":"Do you have ...?","examples":["Do you have a tail?","Do you have mustache on your face?"]},{"name":"What color is ...? Is it ...?","examples":["What color is your bag? Is it red?","What color is your toy digger?Is it yellow?"]},{"name":"Is there...?There's  ...","examples":["Is there a spider in the corner? There's a ladybug in the corner.","Is there a branch on the tree?There are so many new branches on the peachtree."]},{"name":"I drink...from","examples":["I drink milk shake from my cup.","I drink black coffee from the cup."]}]},{"number":71,"name":"Lock","image":"assets/noun-cards/071.jpeg","imageOk":false,"dialogue":"常速语境（名词复述）\nHello, dear darling, \nWhat's this? It is a lock, lock, lock, lock lock lock...\nLook at the lock. \nWhat can you do ?\nYou can use it to keep the door closed. \nHere is the door. Let's lock the door.\nOK the door is locked, now , what else can we lock？\nYou need to lock the window, lock the window, now lock the window. \nWe are ready to go. lock, \"wolf . wolf. wolf. \"\nWhat's that? Oh no, it is my puppy, my dog. I locked my dog inside my house. \nOh silly me. lock , lock","translation":"这段亲子对话围绕“Lock”展开，可结合图片逐句理解和跟读。","words":[],"patterns":[{"name":"What color is it? It's ...          It can be ...or.....","examples":["What color is it? It's a golden beach.It can be golden or black.","What color is it? It's a white rabbit.It can be white or yellow."]},{"name":"What can a... do? I can use sth to do sth","examples":["What can a spade do? I can use the spade to dig a hole.","What can a bucket do? I can use the bucket to fill with sand."]},{"name":"Why do I have sth?","examples":["Why do I have so many bags?","Why do I have so many toys?"]},{"name":"I am gonna do sth","examples":["I am gonna play beachball now.","I am gonna play scooter now."]}]},{"number":72,"name":"Key","image":"assets/noun-cards/072.jpeg","imageOk":true,"dialogue":"常速语境（名词复述）\nHello, everybody, \nlook at this, this is a the key, key key...\nNow look at the key,\nWhat color is it?\nIt's a grey key. A key can be golden too. Or silver. \nThis is a grey key. \nWhat can a key do? \nI can use the key to open the lock. You can use the key to open the lock.\nOh, look what I have got.（look at what I have）\nI have so many keys .\nWhy do I have so many keys? look, this is my key to my front door, this is the key to my back door, this is the key to my locker, this is my key to suitcase,and  this is my car key. \nI am gonna drive now. bye.","translation":"这段亲子对话围绕“Key”展开，可结合图片逐句理解和跟读。","words":[{"word":"golden","ipa":"ˈɡəʊldən","meaning":"金的；金制的;金色的;第五十的;快乐的；幸福的；繁荣的;极其珍贵的；非常有利的;","collocation":"use golden","example":"I can use golden."},{"word":"silver","ipa":"ˈsɪlvə","meaning":"银（化学元素）;银币;银器;银餐具；镀银餐具;银色；银白色；银灰色;银牌；银质奖章;银盐;","collocation":"use silver","example":"I can use silver."},{"word":"locker","ipa":"ˈlɒkə","meaning":"（体育馆等公共场所存放衣物和贵重物品的）锁柜，寄物柜;（冷藏货栈出租给用户存放食物的）冷藏格;","collocation":"use locker","example":"I can use locker."},{"word":"suitcase","ipa":"ˈsuːtˌkeɪs","meaning":"旅行箱；手提箱","collocation":"use suitcase","example":"I can use suitcase."}],"patterns":[{"name":"What color is it? It's ...          It can be ...or.....","example":"Can you use What color is it? It's ...          It can be ...or..... in a sentence?"},{"name":"What can a... do? I can use sth to do sth","example":"Can you use What can a... do? I can use sth to do sth in a sentence?"},{"name":"Why do I have sth?","example":"Can you use Why do I have sth? in a sentence?"},{"name":"I am gonna do sth","example":"Can you use I am gonna do sth in a sentence?"}]},{"number":73,"name":"Hammer","image":"assets/noun-cards/073.jpeg","imageOk":false,"dialogue":"常速语境（名词复述）\nHello, dear darling, \nWhat's this? It's a hammer, hammer……\nI can use the hammer to hit the nails, hit the nails..\nWho can use the hammer?\nCan you use the hammer? \nI don't think that is a good idea. \nCan little girl use the hammer? No, it's too dangerous. \nCan little boy use the hammer? No, it's also too dangerous, What about mummy? \nCan Mummy use the hammer? \nCan Daddy use the hammer? \nMy daddy can use the hammer, DONG DONG DONG, \nMy daddy can use the hammer, hammer hammer.","translation":"这段亲子对话围绕“Hammer”展开，可结合图片逐句理解和跟读。","words":[],"patterns":[{"name":"I can use ... to do sth...","example":"Can you use I can use ... to do sth... in a sentence?"},{"name":"Who can use ...?Can you use ...?","example":"Can you use Who can use ...?Can you use ...? in a sentence?"},{"name":"Can ...use ...? No, it's ...","example":"Can you use Can ...use ...? No, it's ... in a sentence?"}]},{"number":74,"name":"Clock","image":"assets/noun-cards/074.jpeg","imageOk":true,"dialogue":"常速语境（名词复述）\nDI TOCK, CLOCK, CLOCK, Everybody, What's this?\nIt a clock, clock, clock...\nLook at the clock, \nWhat can it do? \nIt can tell you time. \nA clock can tell you time. CUCKOO CUCKOO \nWhat time is it? \nOh, it is the time to get up. What time is It? \nBreakfast time, enjoy your breakfast. CUCKOO CUCKOO \nIt is reading time. Let's read the book. CUCKOO, CUCKOO \nAh, I am so sleepy. \nIt is sleeping time, let's go to the bed. Good night.","translation":"这段亲子对话围绕“Clock”展开，可结合图片逐句理解和跟读。","words":[],"patterns":[{"name":"I'm doing sth...","examples":["I'm learning Enghlish.","I'm interviewing online."]},{"name":"It's...o'clock, I need to do sth...","examples":["It's 9 o'clock. I need to go to school.","It's 6 o'clock. I need to cook dinner."]},{"name":"I want to do sth...","examples":["I want to build a sandcastle.","I want to step in the puddles."]},{"name":"It's... o'clock, it is ...time.Let's do sth...","examples":["It's 7 o'clock,it is breakfast time,Let's have breakfast.","It's 8 o'clock,it is play time,Let's play football."]}]},{"number":75,"name":"Jacket","image":"assets/noun-cards/075.jpeg","imageOk":true,"dialogue":"常速语境（名词复述）\nHello, dear darling, \nWhat's this? \nIt is a jacket, jacket, jacket. \nI am so cold. \nWhy not put on your jacket? Put on your jacket. \nBut I am a little hot. Take off your jacket. \nNow look at this jacket. \nWhat color is it? \nIt's blue and orange. \nDo you have a jacket? \nWhat color is it? \nI have a black jacket. It is very cool. \nWhy not sing a song with me? PUT ON YOUR JACKET, YOUR JACKET, YOUR JACKET.   \nHURRY UP, HURRY UP, HURRY HURRY UP.","translation":"这段亲子对话围绕“Jacket”展开，可结合图片逐句理解和跟读。","words":[],"patterns":[{"name":"I am so ... Why not do sth?","example":"Can you use I am so ... Why not do sth? in a sentence?"},{"name":"What color is it? It's...","example":"Can you use What color is it? It's... in a sentence?"},{"name":"Do you have a...? I have a ...","example":"Can you use Do you have a...? I have a ... in a sentence?"}]},{"number":76,"name":"Jeans","image":"assets/noun-cards/076.jpeg","imageOk":true,"dialogue":"常速语境（名词复述）\nHello，everybody, \nWhat can you see?   \n I can see a pair of jeans jeans.  \nOk, look at the jeans. \nWhat color？   \nI think this is a pair of blue jeans.Blue jeans. \nDo you like the blue jeans?\nI do. Blue jeans make me really cool.You know what.\nThis boy likes blue jeans too.  \nLook. The boy is wearing jeans today.  \nWhy not sing the song with me?  \nJeans today. Jeans today.  \nThe boy is wearing jeans today. Jeans today. Jeans today.  \n I like wearing blue jeans.","translation":"这段亲子对话围绕“Jeans”展开，可结合图片逐句理解和跟读。","words":[],"patterns":[{"name":"What can you see? I can see ...","example":"Can you use What can you see? I can see ... in a sentence?"},{"name":"Do you like ...?I do.","example":"Can you use Do you like ...?I do. in a sentence?"},{"name":"Why not do sth?","example":"Can you use Why not do sth? in a sentence?"}]},{"number":77,"name":"Dress","image":"assets/noun-cards/077.jpeg","imageOk":false,"dialogue":"常速语境（名词复述）\nWho is wearing a dress today? Dress today. Dress today.  \nMom is wearing a dress today. Dress today\\~  \nDress. Everyone looks at this. \nThis is a beautiful pink dress.Dress. Dress. Dress.   \nIt's a pink dress. Oh. Such a beautiful dress.\nI like the dress.\nDo you like the dress? \nThat's very beautiful.  \nMy mom likes to wear a dress.  \nDo you like to wear a dress?  \nYes, I like to wear dresses too.  \n Oh no. Daddy, you cannot wear a dress.   \n Daddy, that's not for you .  \n That is mommy's dress.  \n Girls love dresses.","translation":"这段亲子对话围绕“Dress”展开，可结合图片逐句理解和跟读。","words":[],"patterns":[{"name":"This is a ...Such a ...","example":"Can you use This is a ...Such a ... in a sentence?"}]},{"number":78,"name":"Vest","image":"assets/noun-cards/078.jpeg","imageOk":false,"dialogue":"常速语境（名词复述）\n Who is wearing a vest today? Vest today. Vest today.  \n The baby is wearing a vest today. Vest today\\~  \n Look, everybody. This is a vest.  \n Vest, vest, vest.  \n Look at the vest. It is orange. It's an orange vest.  \n Hmm, it looks so cool. Yes, because it has no sleeves.\n It's very cool to wear in summer.\n What?The robot wants to put on the vest.\n Ok. Let's put it on. \n Put on your vest, your vest, your vest.\n Hurry up, hurry up, hurry hurry up\n She is wearing a vest.","translation":"这段亲子对话围绕“Vest”展开，可结合图片逐句理解和跟读。","words":[{"word":"sleeve","ipa":"sliːv","meaning":"袖子;封套;套筒；衬垫;套管;","collocation":"use sleeve","example":"I can use sleeve."}],"patterns":[{"name":"Who is wearing ...? ... is wearing ...","example":"Can you use Who is wearing ...? ... is wearing ... in a sentence?"},{"name":"It's very ... to ...， because it has (no) ....","example":"Can you use It's very ... to ...， because it has (no) .... in a sentence?"},{"name":"... wants to....Let's do sth...","example":"Can you use ... wants to....Let's do sth... in a sentence?"}]},{"number":79,"name":"T-shirt","image":"assets/noun-cards/079.jpeg","imageOk":false,"dialogue":"常速语境（名词复述）\n Who is wearing a T-shirt today? T-shirt today. T-shirt today.  \n Grandpa is wearing a T-shirt today. T-shirt today\\~  \n Hello everybody. \n Look at this. This is a T-shirt.\n T-shirt, T-shirt...\n What color is the T-shirt?\n It's a green T-shirt. A green T-shirt.  \n Grandpa is wearing a green T-shirt.  \n It's my favorite T-shirt.  \n You know what, grandpa. I have all kinds of T-shirts.  \n Red T-shirt, green T-shirt. yellow T-shirt. blue T-shirt, pink T-shirt, purple T-shirt  \n And my favorite is purple T-shirt.  \n What's your favorite T-shirt?  \n T-shirt. I like T-shirts.","translation":"这段亲子对话围绕“T-shirt”展开，可结合图片逐句理解和跟读。","words":[],"patterns":[{"name":"Who is wearing ... today?... is wearing a ...","example":"Can you use Who is wearing ... today?... is wearing a ... in a sentence?"},{"name":"What color is...?It's a ...","example":"Can you use What color is...?It's a ... in a sentence?"},{"name":"What's your favorite ...?My favorite is...","example":"Can you use What's your favorite ...?My favorite is... in a sentence?"}]},{"number":80,"name":"Socks","image":"assets/noun-cards/080.jpeg","imageOk":false,"dialogue":"常速语境（名词复述）\nHello, dear darling. What's this? It's a sock. Sock. sock, sock.  \nLook at this sock. It's a green sock.  \nDo you wear  one sock only?  \nNo, you wear two socks. A pair of socks.  \nYou wear a pair of socks. Because you have two feet.  \nWhose sock is this？\nhum, so smelly.\n Oh, sorry, it's my sock.\n Oh, daddy, take off your dirty socks. They are so smelly.\n Let's sing a song for daddy.\n Take off your smelly socks. Smelly socks. Smelly socks.\n Hurry up, hurry up, hurry hurry up.\n Daddy!Take off your smelly socks.\n Sock. I wear a pair of socks.","translation":"这段亲子对话围绕“Socks”展开，可结合图片逐句理解和跟读。","words":[],"patterns":[{"name":"Do you wear ...?No, you wear ...","example":"Can you use Do you wear ...?No, you wear ... in a sentence?"},{"name":"Whose ... is this？ It's ...","example":"Can you use Whose ... is this？ It's ... in a sentence?"},{"name":"Take off your ...","example":"Can you use Take off your ... in a sentence?"}]},{"number":81,"name":"Hat","image":"assets/noun-cards/081.jpeg","imageOk":true,"dialogue":"常速语境（名词复述）\nHello,dear darling, \nWhat's this?\nIt's a hat hat hat hat......\nOh, look at this hat. \nWhat color is it? It is a red hat？No, it's a green hat？\nNo, it's a black hat, black hat, black hat. \nOh, put on my hat, look, my hat is on my head. Oh oh, \nWhere is my hat now?\nYour hat is on your shoulder shoulder shoulder. \nThere is a hat on my shoulder. \nThere is a song why don't we sing it and put it on your head. \nReady go, put on your hat, your hat, your hat.\nHurry up hurry up ......\nI wear a hat on my head.","translation":"这段亲子对话围绕“Hat”展开，可结合图片逐句理解和跟读。","words":[],"patterns":[{"name":"Where is my...?There is ...on...","examples":["Where is my crab?There is a crab on your shoulder.","Where is my cap?There is a blue cap on your head."]},{"name":"There is a... why don't we do sth?","examples":["There is a palyground why don't we go to there and play football.","There is a orange juice on the table . Why don't we drink it."]},{"name":"I wear...on...","examples":["I wear a strange dress on my body.","I wear a pink cap on my head."]}]},{"number":82,"name":"Cap","image":"assets/noun-cards/082.jpeg","imageOk":true,"dialogue":"常速语境（名词复述）\nHello,dear darling, \nlook, I've got a cool cap cap cap cap ...\nOh, this is a cap, too.\nWhat color is this cap? \nIt's blue,it is a blue cap. \nWhat about this one?\nIt's a blue cap too.Are they the same kind of blue?\nNo , this is a dark blue cap.This is a light blue cap, light blue cap,dark blue cap light blue cap, dark blue cap… \nWhich one do you like best?\nI like this one.Because it's really cool. \nOh, but it is a little hot. \nSo why don't we take it off?\nTake off your cap,your cap,your cap.","translation":"这段亲子对话围绕“Cap”展开，可结合图片逐句理解和跟读。","words":[],"patterns":[{"name":"I've got a ...(I have = I have got)","examples":["I've got a toy plan.","I haven't got a car."]},{"name":"Are they ...","examples":["Are they black sheep?","Are they your family?"]},{"name":"Which one do you like ?I like ... Because it's ..","examples":["Which one do you like? I like the pink dress, because it's so pretty.","Which one do you like? I like the big one, because it's so cool."]},{"name":"Why don't we do sth?","examples":["Why don't we go to the beach?","Why don't we listen to music and have a drink?"]}]},{"number":83,"name":"Glasses","image":"assets/noun-cards/083.jpeg","imageOk":true,"dialogue":"常速语境（名词复述）\nHello,dear darling,\nWhat are these?\nI can't really see clearly. \nLet me put on my glasses, put on my glasses.\nThere are glasses too. \nLook, there is a pair of glasses.\nI am wearing a pair of several glasses.\nIt helps me see better. \nI wear glasses.\nDoes your mother wear glasses? \nNo, my mother doesn't wear glasses.\nWhat about your daddy?\nDoes your daddy wear glasses?\nOh,yes, my daddy wears glasses and he has a pair of very cool glasses.","translation":"这段亲子对话围绕“Glasses”展开，可结合图片逐句理解和跟读。","words":[{"word":"several","ipa":"ˈsevrəl","meaning":"几个；数个；数人；数件物","collocation":"use several","example":"I can use several."}],"patterns":[{"name":"What are these? Are these ....?","examples":["What are these?Are these your shovels?","What are these?Are these your smelly socks?"]},{"name":".... can protect ....","examples":["Sunhat can protect your face from the strong sunshine.","Sandals can protect your feet from sand."]},{"name":"Don't forget to do sth...","examples":["Don't forget to apply your sunscreen.","Don't forget to eat breakfast."]},{"name":"Do not do sth...,... won't be...","examples":["Do not play close the seaside,it won't be safe.","Do not swim in the deep area,it will be dangerous."]},{"name":"be able to do sth...","examples":["I'm able to solve difficult problems.","Daddy is  able to drive different kinds of cars."]}]},{"number":84,"name":"Sunglasses","image":"assets/noun-cards/084.jpeg","imageOk":true,"dialogue":"常速语境（名词复述）\nHello,dear darling,\nWhat are these? Sunglasses.\nAre these glasses? No. \nEm, I'm wearing glasses.\nBut this pair is a pair of sunglasses ,sunglasses...\nWhat's the difference between them? \nOh, sunglasses are black, they can protect your eyes from the sun. \nOh, the sun is so strong, you need to wear sunglasses. \nSo, when you go to the beach, don't forget to wear your sunglasses. \nBut do not wear your sunglasses all the time. \nFor example, at night.\nDo not wear your sunglasses.Because you won't be able to see anything.","translation":"这段亲子对话围绕“Sunglasses”展开，可结合图片逐句理解和跟读。","words":[{"word":"able","ipa":"ˈeɪbl","meaning":"有才华的；有天赋的;有资格的；胜任的;","collocation":"use able","example":"I can use able."}],"patterns":[{"name":"What are these? Are these ....?","example":"Can you use What are these? Are these ....? in a sentence?"},{"name":".... can protect ....","example":"Can you use .... can protect .... in a sentence?"},{"name":"Don't forget to do sth...","example":"Can you use Don't forget to do sth... in a sentence?"},{"name":"Do not do sth...,... won't be...","example":"Can you use Do not do sth...,... won't be... in a sentence?"},{"name":"be able to do sth...","example":"Can you use be able to do sth... in a sentence?"}]},{"number":85,"name":"Watch","image":"assets/noun-cards/085.jpeg","imageOk":true,"dialogue":"常速语境（名词复述）\nOh, dear darling. This is a watch,and I'm checking on the time. \nOh,this is my watch, watch, watch, watch. \nThis is a watch, and it can tell you the time.\nFor example,  it's six o'clock, I need to get up.\nIt is seven o'clock, I am so hungry,\nI want to eat something, it's breakfast time. \nIt's ten o'clock,it. It is reading time.Let's read a book. \nOh 3 o'clock, it's my swimming time ,\nI gotta go.Bye,I'm gotta swimming.","translation":"这段亲子对话围绕“Watch”展开，可结合图片逐句理解和跟读。","words":[],"patterns":[{"name":"I'm doing sth...","example":"Can you use I'm doing sth... in a sentence?"},{"name":"It's...o'clock, I need to do sth...","example":"Can you use It's...o'clock, I need to do sth... in a sentence?"},{"name":"I want to do sth...","example":"Can you use I want to do sth... in a sentence?"},{"name":"It's... o'clock, it is ...time.Let's do sth...","example":"Can you use It's... o'clock, it is ...time.Let's do sth... in a sentence?"}]},{"number":86,"name":"Umbrella","image":"assets/noun-cards/086.jpeg","imageOk":true,"dialogue":"常速语境（名词复述）\nRain, rain , go away,come again another day.\nLittle JiXiang wants to play,\nRain,rain,go away.\nHello dear darling,\nIt is raining and the baby is not happy. \nWhy?Because I want to play outside.\nWhat? You say I can still play outside.\nBecause there is an umbrella.\nUmbrella...\nWhat can an umbrella do? \nYou open it and stand under it.\nAnd you can walk in the rain.\nSplish splash splish splash. \nNow, I am not afraid of the rain. \nI can jump in the muddy puddles.\nJump ,jump,jump \nI love my umbrella.\nI use an umbrella in the rain.","translation":"这段亲子对话围绕“Umbrella”展开，可结合图片逐句理解和跟读。","words":[{"word":"splash","ipa":"splæʃ","meaning":"溅；泼；泼溅;溅上的污渍;泼溅声；飞溅声;溅起的液体;（向酒水中加入的）少量液体（如苏打水、水）;（与周围颜色形成鲜明对比的）亮色区域;（通常为做样子的）夸示，大肆夸耀;","collocation":"use splash","example":"I can use splash."},{"word":"splish","ipa":"","meaning":"常用词；具体词义见原文","collocation":"use splish","example":"I can use splish."},{"word":"muddy","ipa":"ˈmʌdɪ","meaning":"沾满泥的；多泥的；泥泞的;黯淡的；不鲜亮的;浑浊的；不清澈的;糊涂的；迷糊的;","collocation":"use muddy","example":"I can use muddy."},{"word":"puddle","ipa":"ˈpʌdl","meaning":"（尤指雨水的）小水坑，水洼;一摊;胶土；胶泥;（划桨造成的）旋涡;","collocation":"use puddle","example":"I can use puddle."}],"patterns":[{"name":"It is doing ...","example":"Can you use It is doing ... in a sentence?"},{"name":"What can .... do?  You can do sth...","example":"Can you use What can .... do?  You can do sth... in a sentence?"},{"name":"I am (not) afraid of ....","example":"Can you use I am (not) afraid of .... in a sentence?"},{"name":"I love sth... I use sth...","example":"Can you use I love sth... I use sth... in a sentence?"}]},{"number":87,"name":"Car","image":"assets/noun-cards/087.jpeg","imageOk":true,"dialogue":"常速语境（名词复述）\nZoom,zoom,zoom,zoom \nWhat is this?everybody.\nThis is a car. \nA car can go very fast.\nCome back ,ok.\nHow many wheels can you see？This is a wheel.\nA car has four wheels. \nCan your daddy drive a car? \nYes, my daddy can drive a car. \nWhat about mummy?\nMy mummy can drive a car too.\nBut, what about a baby? \nCan you drive a car? \nNo,because a baby is so small \nA baby can not drive a car.\nA car can go very fast.","translation":"这段亲子对话围绕“Car”展开，可结合图片逐句理解和跟读。","words":[],"patterns":[{"name":"What is this? It is a ...","examples":["What is this?It is a seagull.","What is that?It is a coconut."]},{"name":"Sth can do...","examples":["My bag can hold lots of things.","Robots can do so many things."]},{"name":"What can be...?(被动语态)","examples":["What can be held in your bag?","What can be done by robots?"]},{"name":"Somebody have done...(现在完成时)","examples":["XiaoJiXiang has done his homework.","I have cleaned the floor today."]}]},{"number":88,"name":"Bus","image":"assets/noun-cards/088.jpeg","imageOk":true,"dialogue":"常速语境（名词复述）\nThe wheels on the bus go round and round.\nRound and round round and round....\nHello,dear darling.\nThis is a bus...\nNow,look at this bus. \nIt is a bus, very big.\nWhat is this? It is a wheel.\nA bus has a lot of wheels.\nAnd who are on the bus?\nI see many people. \nThe people on the bus go up and down. \nWhere are they going? \nMaybe they are going to the zoo. \nOk,so why don't we sing the bus song?\nThe people on the bus go up and down..\nI can take a bus...","translation":"这段亲子对话围绕“Bus”展开，可结合图片逐句理解和跟读。","words":[],"patterns":[{"name":"What is this? It is a...         ... has a lot of...","examples":["What is this?It is a crab. A crab has a lot of legs.","What is this?It is a tree. A tree has a lot of leaves."]},{"name":"Who are/is on ...?I see ...","examples":["Who are on the boat? I see two ducks on the boat.","Who is in the building? I see my mom in the building."]},{"name":"Where are they going? Maybe they are going to ...","examples":["Where is he going?He is going to the cinema in the evening.","Where is your mom going?She is going to shopping."]},{"name":"Why don't we do sth?","examples":["Why don't we go to shopping?","Why don't we climb mountains?"]},{"name":"I can do sth...","examples":["I can fly the kite.","I can run very fast."]}]},{"number":89,"name":"Van","image":"assets/noun-cards/089.jpeg","imageOk":false,"dialogue":"常速语境（名词复述）\nHello dear darling.   \nWhat is this? It is a van van van.\nWhat is this? That's right, it's a van.\nIt is a very big car.  \nWe can put many, many things in it.  \nAnd, a driver can drive it to deliver goods.   \nWhat can be delivered?   \nMaybe apples, maybe vegetables.\nWhat about piggies ?  \nOink oink Yes, we can put many many piggies in the van 1,2,3,4 many piggies..  \nWhat about this?  \nElephant！ Let's have a try.  \nSorry , we've tried. It is too big.  \nMy mom can drive a van...","translation":"这段亲子对话围绕“Van”展开，可结合图片逐句理解和跟读。","words":[{"word":"deliver","ipa":"dɪˈlɪvə","meaning":"投递；递送；运送;交付；托付；交托;发表；发布;解救；拯救；使解脱;接生;产下，诞下（孩子）;突然发出；给予;发出（惊叹、噪音等）;拉拢;","collocation":"use deliver","example":"I can use deliver."},{"word":"goods","ipa":"ɡʊdz","meaning":"常用词；具体词义见原文","collocation":"use goods","example":"I can use goods."}],"patterns":[{"name":"What is this? It is a ...","example":"Can you use What is this? It is a ... in a sentence?"},{"name":"Sth can do...","example":"Can you use Sth can do... in a sentence?"},{"name":"What can be...?(被动语态)","example":"Can you use What can be...?(被动语态) in a sentence?"},{"name":"Somebody have done...(现在完成时)","example":"Can you use Somebody have done...(现在完成时) in a sentence?"}]},{"number":90,"name":"Traffic light","image":"assets/noun-cards/090.jpeg","imageOk":false,"dialogue":"常速语境（名词复述）\nGreen says go,green says go,go,go...\nYellow says slow,yellow says slow,slow,slow...\nHello dear darling.\nWhat is this? \nIt is a traffic light...\nThere are three colors.\nRed,yellow,and green.\nGreen says go,go,go.\nAnd yellow says slow,slow,slow.\nAnd the red one says stop. \nHere comes car,stop.\nOk, why don't we sing the traffic light song? \nRed says stop stop...\nA traffic light is red,yellow,and green...","translation":"这段亲子对话围绕“Traffic light”展开，可结合图片逐句理解和跟读。","words":[],"patterns":[{"name":"What is this? It is a ...","examples":["What is this?It is an apple.","What is that?It is a plane."]},{"name":"There are ...","examples":["There are three apples on the table.","There is a ladybug on the leaf."]},{"name":"Why don't we do sth?","examples":["Why don't we go to the beach?","Why don't we play the vollyball now？"]}]},{"number":91,"name":"Boat","image":"assets/noun-cards/091.jpeg","imageOk":false,"dialogue":"常速语境（名词复述）\nHello, little one, \nWhat's this? It's a boat. Boat, boat ...   \nYou can sit in a boat, \nYou can row a boat, row, row ,row your boat.\nI am rowing a boat. \nLook! I'm rowing a boat happily.   \nOK, you can row this boat to travel on the water.   \nWhy don't we sing the“Row, Row, Row your boat”song?   \nRow, Row, Row your boat,   \nMerrily down the stream.   \nMerrily, Merrily, Merrily, Merrily, Life is but a dream.","translation":"这段亲子对话围绕“Boat”展开，可结合图片逐句理解和跟读。","words":[],"patterns":[{"name":"You can do sth...","examples":["You can put on your socks by yourself.","You can clean the room."]},{"name":"I am doing sth...","examples":["I am playing game.","I am drinking water."]},{"name":"Why don't we do sth?","examples":["Why don't we go to the playground?","Why don't we learn English together?"]}]},{"number":92,"name":"Sea","image":"assets/noun-cards/092.jpeg","imageOk":false,"dialogue":"常速语境（名词复述）\nHello, dear daring, \nWhat's this? \nIt is big, it is blue, it is the sea, sea, sea…\nWhat's this? Yes, it's the sea. \nGood job! The sea is blue. There are many many waves. \nWhat can you see in the sea? \nI can see fish swimming in the sea, swim, swim, swim. \nAnd I can see the sharks. Remember the shark song ?\nBaby shark doo doo doo doo doo doo. \nOK, that's the very funny song, you can listen to that.\nAnd you can also see a boat on the sea. \nOK, I'm gonna go. Bye-bye. \nI'm gonna row a boat on the sea.\nThere are many fishes in the sea.","translation":"这段亲子对话围绕“Sea”展开，可结合图片逐句理解和跟读。","words":[],"patterns":[{"name":"Somebody wants to do...","examples":["There are so many cars on the road.","There are two kites in the sky."]},{"name":"I like to go to ...         I like( to go doing) ...去做某事","examples":["I like to go to play the seesaw. I like to go playing the seesaw.","I like to go riding a bike. I like to go riding a bike."]},{"name":"If you want to do...  you can do sth...","examples":["If you want to drink water, you can take your cup by yourself.","If you want to go to the beach, you can take off your shoes."]}]},{"number":93,"name":"Sun","image":"assets/noun-cards/093.jpeg","imageOk":false,"dialogue":"常速语境（名词复述）\nToday is so hot! \nWhy is it so hot?   \nBecause of the Sun. Sun ….  \nWhat's this? \nThe Sun. Very good! Now look at the sun.   \nSometimes it's red, sometimes it's yellow, and it's always hot.   \nWhen you have a very strong sun,\nYou can play outside, but you have to protect yourself very well.   \nDon't forget to wear your cap.  \nPut on your cap, and you can enjoy the sun outside.   \nAnd also, you need the sun glasses, sun glasses, \nPut on the sun glasses and you can play in the sun.   \nWhat can you play on a sunny day?   \nYou can play on the outside.   \nWoo, I wanna go now, bye!","translation":"这段亲子对话围绕“Sun”展开，可结合图片逐句理解和跟读。","words":[],"patterns":[{"name":"Why is/are it/you/they...?","examples":["Why is it so cold?","What are you so dirty?"]},{"name":"Look at ...","examples":["Look at the rabbit!Sometimes it's white,sometimes it's black,and it's always cute."]},{"name":"You can ..., but you have to do sth...","examples":["You can play outside,but you have to wear your raincoat."]},{"name":"Don't forget to do sth...","examples":["Don't forget to take your bag to go to school.","Don't forget to pay for it."]},{"name":"What can you ... on a sunny day?","examples":["What can you say on the meeting?","What can you do on a  rainy day?"]}]},{"number":94,"name":"Moon","image":"assets/noun-cards/094.jpeg","imageOk":true,"dialogue":"常速语境（名词复述）\nWoo,woo,woo.. \nWhat's this? This is the moon, moon,……\nWhat's this? The moon. \nVery good! \nWhat color is the moon? \nUmm, it's silver. It's a silver moon. \nWhen the moon comes out, the owl comes out, and it says “woo,woo,woo…”, Funny. \nNow, we're going listen to a funny poem called“Hey Diddle, Diddle”. \nListen to this: Hey diddle diddle, the cat and the fiddle, \nThe cow jumped over the moon. The little dog laughed to see such fun, \nAnd the dish ran away with the spoon. Moon, moon.\nI can see the moon in the night sky.","translation":"这段亲子对话围绕“Moon”展开，可结合图片逐句理解和跟读。","words":[{"word":"silver","ipa":"ˈsɪlvə","meaning":"银（化学元素）;银币;银器;银餐具；镀银餐具;银色；银白色；银灰色;银牌；银质奖章;银盐;","collocation":"use silver","example":"I can use silver."},{"word":"fiddle","ipa":"ˈfɪdl","meaning":"小提琴;诈骗；欺诈;虚度光阴；无所事事;细活；繁琐之事;餐具围框（防止天气恶劣船摇摆时餐具滚落）;","collocation":"use fiddle","example":"I can use fiddle."},{"word":"dish","ipa":"dɪʃ","meaning":"盘（子）；碟（子）;一盘（或一碟）食物;一道菜；菜肴;一盘（或一碟）的量;盘状物；碟形物;凹陷；凹处;有魅力的人;喜欢的事；擅长的事;","collocation":"use dish","example":"I can use dish."}],"patterns":[{"name":"What color is...?  It's a ...","example":"Can you use What color is...?  It's a ... in a sentence?"},{"name":"... going to do...","example":"Can you use ... going to do... in a sentence?"},{"name":"I can see....","example":"Can you use I can see.... in a sentence?"}]},{"number":95,"name":"Flower","image":"assets/noun-cards/095.jpeg","imageOk":true,"dialogue":"常速语境（名词复述）\n The flowers are so fragrant.\n Look at this, dear darling.\n Flower, flower…\n Look, Susan has got so many flowers.   \n Let's count how many.   \n One, two, three, four, five, six, seven, eight, nine, ten, eleven,   \n There are eleven flowers.   \n What color are they? \n They're pink. They're pink flowers.   \n What about these flowers? One,two. I see two flowers, \n I see an orange flower and I see a light orange flower.\n They are both orange. \n I like flowers because they are so beautiful.  \n Do you like flowers, too?","translation":"这段亲子对话围绕“Flower”展开，可结合图片逐句理解和跟读。","words":[],"patterns":[{"name":"... has got ....","examples":["John has got some presents.","I have cooked dinner with my mom."]},{"name":"There are ...","examples":["There are 5 bananas on the table.","There are so many kites in the sky."]},{"name":"I see ... and I see ....","examples":["I see a puppy and a cat in the park.","I see a red balloon and a blue balloon."]},{"name":"I like .....because they are ....","examples":["I like dogs,because they are so cute.Do you like dogs？","I like butterflies,because they are so beautiful.Do you like butterfies?"]}]},{"number":96,"name":"Grass","image":"assets/noun-cards/096.jpeg","imageOk":true,"dialogue":"常速语境（名词复述）\nHello dear darling, What's this?\nThis is grass...  \nWhat color is the grass?  \nIt's green. It's green grass.  \n And grass can be very long.  \n It can be Swishy.  \n The grass can go swishy,swishy, swishy.  \n Ok,a grass can be yummy food,  \n What? No, we don't eat grass.  \n Some animals do. Look at this. This is a sheep.  \n A sheep likes to eat grass. \n A sheep likes to eat grass.  \n What about this animal? \n Oh,the bull.  \n The bull likes to eat grass too,  \n The bull likes to eat grass.  \n What about the lion? \n Roar. No, a lion doesn't like the grass.\n Cows and sheep eat grass.","translation":"这段亲子对话围绕“Grass”展开，可结合图片逐句理解和跟读。","words":[{"word":"swishy","ipa":"ˈswɪʃɪ","meaning":"沙沙移动的；窸窣摆动的;女里女气的；娘娘腔的;","collocation":"use swishy","example":"I can use swishy."}],"patterns":[{"name":"... can be...,it can be...","examples":["A rabbit can be white, it can be black."]},{"name":"... don't do sth...","examples":["Monkeys don't eat meat.","My daddy and my mommy don't work today."]},{"name":"... likes to do...","examples":["My friends like to play tennis.","Ruby likes to eat bread."]},{"name":"... doesn't like ...","examples":["My grandma doesn't like the candy.","My classmate doesn't like math."]}]},{"number":97,"name":"Spring","image":"assets/noun-cards/097.jpeg","imageOk":false,"dialogue":"常速语境（名词复述）\nHi, dear darling,\nNow we are gonna look at the four seasons.\nIn the year, there are four seasons,\nThe first season is called Spring Spring Spring Spring...\nSpring is very beautiful.\nBecause it is spring ,it gets warmer.\nAnd all the flowers bloom.\nFlowers bloom in spring.\nThey are so fragrant and grass turns green.\nThe grass turns green and trees turn green too.\nYou can see little little little sprouts coming out.\nAnd the river flows gurgle and gets windy.\nYou can fly a kite.\nSpring is so beautiful.","translation":"这段亲子对话围绕“Spring”展开，可结合图片逐句理解和跟读。","words":[{"word":"bloom","ipa":"bluːm","meaning":"花；花朵;盛开；开花的状态;（统称）花;红润；健康的光泽;（水果、树叶等表面的）粉衣，粉霜;（新硬币的）涂层，表面层;水华（指浮游生物等的过量繁殖）;（油漆面的）模糊不清，浑浊;熟铁坯；铁块；钢块；初轧方坯；大方坯;","collocation":"use bloom","example":"I can use bloom.","sourceExample":"Harry carefully picked the bloom.","sourceTranslation":"哈里小心翼翼地采下那朵花。"},{"word":"fragrant","ipa":"ˈfreɪɡrənt","meaning":"香的；芳香的；芬芳的","collocation":"use fragrant","example":"I can use fragrant.","sourceExample":"fragrant oils and perfumes","sourceTranslation":"香薰油和香水"},{"word":"sprout","ipa":"spraʊt","meaning":"发芽；抽芽；萌芽;生长;突然出现;","collocation":"use sprout","example":"I can use sprout.","sourceExample":"It only takes a few days for beans to sprout.","sourceTranslation":"只要几天豆子就能发芽。"},{"word":"gurgle","ipa":"ˈɡɜːɡl","meaning":"（液体流动时发出的）汩汩声，潺潺声;（尤指婴儿发出的）咯咯声;","collocation":"use gurgle","example":"I can use gurgle.","sourceExample":"a gurgle of laughter","sourceTranslation":"咯咯的笑声"}],"patterns":[{"name":"What ... is this/it/that?","examples":["What time is it?","What animal is that?"]},{"name":"Do you still remember....?","examples":["Do you still remember your first teacher?","Do you still remember your first present?"]},{"name":"There are ... in ....","examples":["There are twelve months in a year.","There are ten fingers on your hand."]},{"name":"What makes ...very ....?","examples":["What makes your mom so excited?","What makes you so happy?"]},{"name":"What can you do ...?         You can do sth and you can do sth...","examples":["What can you do with your shovel?You can dig sand and soil with your shovel.","What can you do with your cup?You can drink water with your cup."]},{"name":"Why don't we do sth?","examples":["Why don't we go and play football?","Why don't we go and step in the water?"]}]},{"number":98,"name":"Summer","image":"assets/noun-cards/098.jpeg","imageOk":false,"dialogue":"常速语境（名词复述）\n Hello, dear darling\n Today, we are gonna look at the second season.\n It is called summer summer...\n Now summer is a very hot season.It's so hot.\n And in summer Susan wants to eat ice cream, ice cream.\n And it makes me feel cool.\n And I like to go to the sea.\n I like to go swimming in the sea.\n It's so cool or you can go rowing a boat.\n It's also very cool.\n And if you want to stay inside, you can turn on the AC.\n And it will make you feel cool.\n This is summer.\n It's a very hot season.","translation":"这段亲子对话围绕“Summer”展开，可结合图片逐句理解和跟读。","words":[],"patterns":[{"name":"Somebody wants to do...","example":"Can you use Somebody wants to do... in a sentence?"},{"name":"I like to go to ...","example":"Can you use I like to go to ... in a sentence?"},{"name":"If you want to do...  you can do sth...","example":"Can you use If you want to do...  you can do sth... in a sentence?"}]},{"number":99,"name":"Autumn","image":"assets/noun-cards/099.jpeg","imageOk":false,"dialogue":"常速语境（名词复述）\nHello dear darling.  \nWhat's this? This is autumn autumn autumn...  \nAutumn is the third season.  \nDo you still remember the first one?  \nThe first season is spring.  \nThe second season is summer.  \nAnd the third season is autumn.  \nAnd in American English, autumn is also called fall,  \nBecause all the leaves fall down.And the leaves turn yellow and red.  \nIf you look at the hill and our city.It's so beautiful.\nYou can pick up the beautiful leaves.You can go crunching on the leaves.\nAutumn is very beautiful too.\nIn autumn, leaves turn yellow and red.","translation":"这段亲子对话围绕“Autumn”展开，可结合图片逐句理解和跟读。","words":[{"word":"crunch","ipa":"krʌntʃ","meaning":"嘎吱嘎吱地嚼;使发出嘎吱嘎吱的声音;把…压碎；把…揉成一团;","collocation":"use crunch","example":"I can use crunch."}],"patterns":[{"name":"Do you remember...?","example":"Can you use Do you remember...? in a sentence?"},{"name":"You can do sth...You can go doing sth...","example":"Can you use You can do sth...You can go doing sth... in a sentence?"}]},{"number":100,"name":"Winter","image":"assets/noun-cards/100.jpeg","imageOk":false,"dialogue":"常速语境（名词复述）\nHello dear darling.\nNow we are gonna look at the last season.\nIt's called winter winter winter...\nWhat season is this? Winter.\nNow do you still remember the first three seasons?\nSpring summer fall winter.\nThere are the four seasons in a year.\nWhat makes winter very special?\nIt's so cold and it snows.\nI love the snow.\nThe snow is so beautiful . It's white.\nWhat can you do with the snow?\nYou can play snow fight,And you can make a snowman.\nThe snowman is so cute.\nNow look! it's snowing\nWhy don't we go and make a snowman?\nWinter winter winter\nIn winter, it's snows.","translation":"这段亲子对话围绕“Winter”展开，可结合图片逐句理解和跟读。","words":[],"patterns":[{"name":"What ... is this/it/that?","example":"Can you use What ... is this/it/that? in a sentence?"},{"name":"Do you still remember....?","example":"Can you use Do you still remember....? in a sentence?"},{"name":"There are ... in ....","example":"Can you use There are ... in .... in a sentence?"},{"name":"What makes ...very ....?","example":"Can you use What makes ...very ....? in a sentence?"},{"name":"What can you do ...?","example":"Can you use What can you do ...? in a sentence?"},{"name":"Why don't we do sth?","example":"Can you use Why don't we do sth? in a sentence?"}]}];
